let drawerSource=null;
const ui={setupStep:0,range:90,review:'all',filter:'all',scenario:'actual',settings:'profile',mobile:false};
function load(){if(!currentUser)return;try{state={...freshState(currentUser),...JSON.parse(localStorage.getItem(KEY+'-'+currentUser)||'null')};}catch{state=freshState(currentUser);}upgradeState(state);}
function persist(){try{localStorage.setItem(KEY+'-'+currentUser,JSON.stringify(state));}catch{toast('当前浏览器未允许保存，关闭页面前请导出决定。');}}
load();
