const iconPaths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M16 8l-3 5-5 3 3-5z',wallet:'M4 6h15v14H4z M4 6V4h13 M15 11h6v5h-6z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',history:'M4 5v5h5 M4 10a8 8 0 1 1 0 6 M12 7v5l3 2',plus:'M12 5v14 M5 12h14',arrow:'M4 12h15 M13 6l6 6-6 6',external:'M14 4h6v6 M20 4l-9 9 M10 5H4v15h15v-6',close:'M6 6l12 12 M18 6L6 18',menu:'M4 6h16 M4 12h16 M4 18h16',chevron:'M9 5l7 7-7 7',back:'M20 12H5 M11 6l-6 6 6 6',check:'M5 12l4 4L19 6',bell:'M5 16h14l-2-3V8a5 5 0 0 0-10 0v5z M10 20h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 3h4l1 3 3 1 3 3v4l-3 1-1 3-3 3h-4l-1-3-3-1-3-3v-4l3-1 1-3z',wave:'M3 10v4 M7 6v12 M12 3v18 M17 7v10 M21 10v4',chart:'M3 18l6-7 4 3 8-10 M3 3v18h18',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',nodes:'M7 5h10 M7 19h10 M5 7v10 M19 7v10 M3 3h4v4H3z M17 3h4v4h-4z M3 17h4v4H3z M17 17h4v4h-4z',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v1',edit:'M4 16l12-12 4 4L8 20H4z M13 7l4 4',link:'M9 8l2-2a5 5 0 0 1 7 7l-2 2 M15 16l-2 2a5 5 0 0 1-7-7l2-2 M8 16l8-8',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',logout:'M9 4H4v16h5 M9 12h12 M16 7l5 5-5 5',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',minus:'M5 12h14',tag:'M3 4h8l10 10-7 7L3 10z M7 7h.01',pause:'M8 5v14 M16 5v14',trash:'M4 6h16 M9 3h6 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6'};
function icon(n,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[n]||iconPaths.info}"/></svg>`;}
function logo(){return `<span class="logo" aria-label="My Best Choice"><img class="logo-mark" src="/assets/mark.svg" alt="" width="40" height="40"><span class="brand-word"><span class="brand-my">My</span><span class="brand-main">Best Choice</span></span></span>`;}
let artId=0;
function art(type='earbuds',cls=''){if(type==='earbuds'||type==='gpu')return `<img class="product-art photo-art ${cls}" src="/assets/${type==='gpu'?'studio':'earbuds'}.webp" alt="${type==='gpu'?'创作设备场景示意':'耳机外观示意，非真实商品实拍'}" loading="lazy">`;const n=++artId;let shape='';if(type==='gpu')shape=`<rect x="33" y="54" width="235" height="108" rx="18" fill="#3b4845"/><rect x="43" y="62" width="213" height="90" rx="12" fill="#263833"/><circle cx="102" cy="106" r="34" fill="#61736a"/><circle cx="196" cy="106" r="34" fill="#61736a"/>${[102,196].map(x=>`<circle cx="${x}" cy="106" r="25" fill="none" stroke="#a0aea1" stroke-width="2" stroke-dasharray="4 5"/><circle cx="${x}" cy="106" r="8" fill="#c7d0bd"/>`).join('')}<path d="M268 72h10v75h-10 M59 162v13h150v-13" fill="#929b8b"/><path d="M56 175v5m10-5v5m10-5v5m10-5v5m10-5v5" stroke="#b8955e" stroke-width="5"/>`;else if(type==='stand')shape=`<path d="M113 38h78l-33 95h-79z" fill="#b6bdb3"/><path d="M191 38l8 5-33 96-8-6z" fill="#7b8a80"/><path d="M119 133l-10 35h99v13H63v-13h30l11-35z" fill="#85978c"/><path d="M111 54h47l-22 63H90z" fill="#d5dbd1"/>`;else shape=`<defs><linearGradient id="case${n}" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#e1e6d9"/><stop offset=".5" stop-color="#b4c1af"/><stop offset="1" stop-color="#849d88"/></linearGradient><linearGradient id="bud${n}" x1="0" x2="1"><stop stop-color="#4f6556"/><stop offset=".55" stop-color="#849780"/><stop offset="1" stop-color="#40584b"/></linearGradient></defs><ellipse cx="150" cy="180" rx="100" ry="10" fill="#334e3c" opacity=".1"/><path d="M58 113c0-14 12-26 28-26h128c16 0 28 12 28 26v38c0 23-21 34-91 34s-93-11-93-34z" fill="url(#case${n})"/><path d="M59 117q91 20 182 0" stroke="#6c866d" stroke-width="1.5" fill="none" opacity=".6"/><rect x="145" y="145" width="12" height="3" rx="1.5" fill="#43634e"/><g transform="rotate(-18 105 61)"><rect x="89" y="43" width="23" height="60" rx="11" fill="url(#bud${n})"/><ellipse cx="101" cy="40" rx="27" ry="22" fill="url(#bud${n})"/><ellipse cx="82" cy="36" rx="9" ry="13" fill="#384e40"/><path d="M101 24v9" stroke="#b9c7ae" stroke-width="2" stroke-linecap="round"/></g><g transform="rotate(18 199 58)"><rect x="183" y="40" width="23" height="60" rx="11" fill="url(#bud${n})"/><ellipse cx="195" cy="37" rx="27" ry="22" fill="url(#bud${n})"/><ellipse cx="214" cy="33" rx="9" ry="13" fill="#384e40"/><path d="M193 22v8" stroke="#b9c7ae" stroke-width="2" stroke-linecap="round"/></g>`;return `<svg class="product-art ${cls}" viewBox="0 0 300 210" role="img" aria-label="${type==='gpu'?'创作显卡示意':type==='stand'?'桌面支架示意':'通勤耳机示意'}">${shape}</svg>`;}
function btn(label,action,cls='',attrs=''){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;}
function link(label,path,cls='btn'){return `<a class="${cls}" href="${path}" data-nav>${label}</a>`;}
function badge(s,cls=''){return `<span class="badge ${cls}">${s}</span>`;}
function amount(n,cls=''){return `<span class="money ${cls}"><span class="currency">HK$</span>${n==null?'—':fmt(n)}</span>`;}
function empty(title,body,action){return `<div class="empty"><div class="symbol">${icon('compass')}</div><h3>${title}</h3><p>${body}</p>${action||''}</div>`;}
function field(name,label,value='',type='text',hint='',attrs=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${protectUserText(value)}" ${attrs}>${hint?`<span class="caption">${hint}</span>`:''}</div>`;}
function textarea(name,label,value='',hint=''){return `<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}">${protectUserText(value)}</textarea>${hint?`<span class="caption">${hint}</span>`:''}</div>`;}
function publicNav(){return `<header class="public-nav">${link(logo(),'/','')}<span class="nav-note">Four perspectives. Your decision.</span>${languageButton()}${link('开始使用 '+icon('arrow','sm'),'/login','btn sm')}</header>`;}
function landing(){return `${publicNav()}<main id="main" class="public-main"><section class="hero"><div><div class="eyebrow">A little clarity before you buy</div><h1>先想清楚，<br>再把钱花在<br><em>值得的地方。</em></h1><p class="lede">比较价格与质量，提前安排想买的东西。<br>让每次购买，都有自己的理由。</p><div class="actions">${link('开始检查购买 '+icon('arrow'),'/login','btn primary')}${link('提前规划需求','/login?next=needs','btn')}</div><p class="hero-note">价格只是一个理由，你的用途和计划也值得被看见。</p></div><div class="hero-preview"><div class="preview-card"><div class="preview-head"><div class="eyebrow">ONE PURCHASE, MORE PERSPECTIVES</div><h3 style="margin-top:9px">Aster One 通勤耳机</h3><p class="caption">黑色标准套装 · 示例情境</p></div><div class="between" style="align-items:end"><div><p class="caption">当前记录到手价</p>${amount(499,'green')}</div>${badge('计划内余 HK$101','green')}</div><svg class="preview-chart" viewBox="0 0 500 145" role="img" aria-label="示例价格从599波动至499"><path d="M4 26H496 M4 68H496 M4 110H496" stroke="#D7DAD8" stroke-width=".7"/><path d="M4 30l38 0 38 25 38-8 38 30 38-18 38 30 38-5 38 18 38-9 38 20 38-6 32 12" fill="none" stroke="#167A68" stroke-width="2.4"/><circle cx="492" cy="119" r="4" fill="#167A68"/></svg><div class="preview-quotes"><div class="blue"><span>正在使用的我</span>它能解决现在的问题吗？</div><div class="green-tone"><span>精打细算的我</span>价格在计划内，也要看总成本。</div><div class="amber"><span>感受当下的我</span>我期待安静的通勤。</div><div class="purple"><span>在意形象的我</span>推荐不必替我做决定。</div></div></div><div class="hero-product">${art()}</div><div class="floating-note">${icon('check','sm')} 好价格，是开始思考的理由。</div></div></section><section class="path-intro"><div class="eyebrow">TWO WAYS TO START</div><h2 style="margin-top:9px">眼前的心动，未来的打算。</h2><div class="grid-2"><div class="path-card"><span class="num">01 / 此刻想买</span><h3>把商品、价格和自己的理由放在一起。</h3><p>对齐平台条件，读懂好评与差评，再听听四个价值视角。买、等或跳过，都可以留下依据。</p>${link('检查一件商品 '+icon('arrow','sm'),'/login','text-btn')}</div><div class="path-card"><span class="num">02 / 提前准备</span><h3>先找到方向，再等合适的机会。</h3><p>把未来可能需要的东西列入计划，逐步准备金额。值得重新评估时，再看具体商品。</p>${link('建立未来目标 '+icon('arrow','sm'),'/login?next=needs','text-btn')}</div></div></section><footer class="public-footer"><span>My Best Choice · Four perspectives. Your decision.</span><span>当前使用示例账户与商品数据，未连接真实订单。</span></footer></main>`;}
function auth(path){const mode=path.includes('signup')?'signup':path.includes('recover')?'recover':'login';return `${publicNav()}<main id="main" class="auth-layout"><aside class="auth-aside"><div class="eyebrow">YOUR PURCHASE, YOUR REASONS</div><h1>留一点空间，<br>给自己的判断。</h1><p>在价格、期待和财务计划之间，找到适合你的选择。</p><div class="auth-quote">“我想知道的，<br>不只是它有没有打折。”</div></aside><section class="auth-card panel"><h2>${mode==='login'?'欢迎来到 My Best Choice':mode==='signup'?'创建你的购买档案':'找回账户'}</h2><p class="small muted">${mode==='login'?'先登录，再开始你的购买计划。':'正式账户服务尚未接入，当前可使用下方示例账户。'}</p><div class="note-banner">${icon('shield')}<span>当前为可交互示例。选择账户即可进入，不收集密码，也未连接银行或购物平台。</span></div><button class="demo-login" data-action="login" data-user="chen"><div><strong>陈晴 · 检查眼前的耳机</strong><span>价格、评价、四个我与下单后新发现</span></div>${icon('arrow')}</button><button class="demo-login" data-action="login" data-user="creator-b"><div><strong>创作者 B · 提前规划显卡</strong><span>未来需求、资金准备与候选关注</span></div>${icon('arrow')}</button><div class="divider" style="margin:24px 0 18px"></div><div class="between caption">${link(mode==='signup'?'返回登录':'注册账户','/signup'===path?'/login':'/signup','text-btn')}${link('找回账户','/recover','text-btn')}</div><p class="caption" style="margin-top:13px">你的示例决定保存在当前浏览器，可在设置中导出或重置。</p></section></main>`;}
function setup(){const s=ui.setupStep;return `${publicNav()}<main id="main" class="auth-layout"><aside class="auth-aside"><div class="eyebrow">A SMALL START</div><h1>先认识你的想法，<br>再看商品的说法。</h1><p>没有标准的消费人格。你可以跳过可选问题，之后随时修改。</p></aside><section class="auth-card panel"><div class="step-dots">${[0,1,2].map(i=>`<span class="${s>=i?'active':''}"></span>`).join('')}</div><p class="caption">${s+1} / 3</p><h2 style="margin:8px 0 20px">${['你的资料，由你决定','你比较重视什么','怎样安排这笔钱'][s]}</h2><form id="setup-form">${s===0?`<div class="stack"><p class="muted">My Best Choice 只使用你主动填写的用途、计划和决定记录。每条归纳都可以查看依据和纠正。</p><p class="hint">浏览器历史、社交媒体与聊天记录仍是未来概念，当前没有读取。</p><label class="check-row"><input type="checkbox" name="consent" required>我了解当前使用示例资料，决定记录保存在本浏览器。</label></div>`:s===1?`${field('name','怎样称呼你',state.profile.name)}<p class="caption" style="margin-bottom:10px">可多选，也可以不选。</p><div class="pill-choices">${['实际用途','价格与质量','体验与外观','长期计划','我还不确定'].map(v=>`<label class="choice"><input type="checkbox" name="priority" value="${v}" ${state.profile.priorities.includes(v)?'checked':''}>${v}</label>`).join('')}</div>`:`<p class="muted" style="margin-bottom:20px">每件商品都可以单独确认计划金额。没有填写时，系统会明确说“财务条件未确认”。</p><div class="field"><label for="planning">默认计划方式</label><select id="planning" name="planning"><option>每笔购买单独填写</option><option>先建立长期目标</option></select></div><p class="hint">不要求收入证明，也不读取银行余额。</p>`}<div class="drawer-actions"><button type="submit" class="btn primary">${s===2?'进入我的首页':'下一步'} ${icon('arrow','sm')}</button>${s>0?btn('上一步','setup-back'):''}${s===1?btn('暂时跳过','setup-skip'):''}</div></form></section></main>`;}
function shell(content,path){const nav=[['home','home'],['needs','compass'],['proposals','spark'],['plans','wallet'],['watchlist','eye'],['decisions','history']];const root=path.split('/')[1]||'home';return `<aside class="sidebar ${ui.mobile?'open':''}">${link(logo(),'/home','')}<p class="tagline">Four perspectives. Your decision.</p><button class="icon-btn mobile-close" style="display:${ui.mobile?'flex':'none'}" data-action="mobile-close" aria-label="关闭导航">${icon('close')}</button><nav aria-label="主要导航">${nav.map(([r,i])=>link(`${icon(i)}<span>${paths[r]}</span>${r==='watchlist'&&state.watch.length?`<span class="count">${state.watch.length}</span>`:''}`,`/${r}`,`nav-item ${root===r?'active':''}`)).join('')}</nav>${link(icon('plus')+' 检查商品','/products/new','btn primary add-btn')}<div class="sidebar-bottom">${link(`<span class="profile-dot">${e(displayPlain(state.profile.name).slice(0,1))}</span><span><span style="display:block;font-size:13px">${e(state.profile.name)}</span><span class="caption">资料与设置</span></span>`, '/settings','row')}<div class="caption" style="font-size:10px;margin-top:18px">${icon('shield','sm')} 示例资料 · 本地保存</div></div></aside><div class="workspace"><header class="topbar"><button class="icon-btn mobile-menu" data-action="mobile-open" aria-label="打开导航">${icon('menu')}</button><div class="breadcrumb"><span>我的 My Best Choice</span>${icon('chevron','sm')}<span>${paths[root]||'购买决定'}</span></div><div class="topbar-actions">${languageButton()}<span class="caption">把理由留下，把主动权留给自己。</span>${badge('<i class="dot"></i> 示例数据','outline')}<button class="icon-btn" data-action="notifications" aria-label="查看变化提醒">${icon('bell')}</button></div></header><main id="main" class="content">${content}</main></div>`;}
function heading(title,subtitle='',actions=''){return `<div class="page-heading between"><div><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${actions}</div>`;}
function miniProduct(p){return `<div class="mini-art">${art(p.art)}</div>`;}
function home(){const goal=state.goals.find(g=>g.status!=='archived');return `<p class="welcome-greeting">${e(state.profile.name)}，欢迎回来</p>${heading('今天先看什么','眼前的心动，未来的打算，都可以慢慢想清楚。',link(icon('plus')+' 检查商品','/products/new','btn primary'))}<div class="dashboard-grid"><section class="panel feature-panel"><div class="eyebrow">A LITTLE CLARITY</div><h2 style="margin-top:13px">好价格之外，<br>也看看自己的理由。</h2><p>你可以先核对商品证据，也可以先确认自己的用途和计划。</p>${link('看看这副通勤耳机 '+icon('arrow','sm'),'/products/earbud-aster','btn white sm')}<div class="art">${art()}</div></section><section class="panel"><div class="between"><h3>提前一点，准备想要的生活。</h3>${icon('compass','green')}</div><p class="muted" style="font-size:13px;margin:15px 0 20px">${goal?'一个已经确认的方向，正在等待合适的候选与时机。':'还没锁定型号也没关系。先把可能需要的方向留在这里。'}</p>${goal?`<p style="font-size:17px;margin-bottom:17px">${e(goal.title)}</p><div class="progress"><span style="width:${funding(goal).progress}%"></span></div><div class="between caption" style="margin-top:9px"><span>已预留 ${hk(goal.reserved)}</span><span>计划目标 ${hk(goal.target)}</span></div>${link('查看我的目标 '+icon('arrow','sm'),'/needs/'+goal.id,'text-btn')}`:link('建立未来需求 '+icon('arrow','sm'),'/needs','text-btn')}</section></div><div class="home-metrics"><div><span class="number">${state.goals.filter(g=>g.status!=='archived').length.toString().padStart(2,'0')}</span><p class="caption">正在准备的目标</p></div><div><span class="number">${state.watch.length.toString().padStart(2,'0')}</span><p class="caption">观察中的商品</p></div><div><span class="number">${state.decisions.length.toString().padStart(2,'0')}</span><p class="caption">已留下的决定</p></div></div><div class="dashboard-grid"><section><div class="section-label"><h2>最近的决定</h2>${link('全部记录 '+icon('arrow','sm'),'/decisions','text-btn')}</div>${state.decisions.length?state.decisions.slice(0,3).map(d=>decisionRow(d,true)).join(''):empty('还没有需要解释的旧决定','从一件商品开始。你可以买、等待，或决定现在不需要。',link('检查一件商品','/products/new','btn sm'))}<div style="margin-top:22px" class="teaser-row"><div><h3>低价，也可能暂时用不上。</h3><p>HK$99 的桌面支架，值得成为第三个吗？</p></div>${link(icon('arrow'),'/products/stand-mini','icon-btn')}</div></section><section><div class="section-label"><h2>值得留意的变化</h2>${link('观察清单','/watchlist','text-btn')}</div>${state.changes.length?state.changes.slice(0,3).map(c=>`<a data-nav href="/changes/${c.id}" class="mini-activity"><span class="activity-mark">${icon('chart','sm')}</span><div><h4>${c.kind==='price'?'发现新的同款报价':'发现更合适的候选'}</h4><p class="caption">${c.kind==='price'?`${hk(c.oldPrice)} → ${hk(c.newPrice)}，先核对条件再决定。`:'价格不是唯一的比较条件。'}</p></div></a>`).join(''):`<div class="mini-activity"><span class="activity-mark">${icon('eye','sm')}</span><div><h4>还没有新的变化</h4><p class="caption">只关注你确认的方向和商品，不替你制造新的购买欲望。</p></div></div>`}<div class="mini-activity"><span class="activity-mark">${icon('file','sm')}</span><div><h4>你的理由，随时可以修改</h4><p class="caption">修改当前想法，不会抹去过去为什么那样决定。</p>${link('查看我的资料','/settings','text-btn')}</div></div></section></div>`;}
function legacyNeeds(){const active=state.goals.filter(g=>g.status!=='archived'),archived=state.goals.filter(g=>g.status==='archived');return `${heading('未来需求','先确定方向，再关注具体商品。AI 提议由你确认，目标也可以自己建立。',btn(icon('plus')+' 新建目标','new-goal','primary'))}${!state.dismissedProposal?`<section class="panel section" style="background:#E8EDE4"><div class="between wrap"><div class="row">${icon('spark','green')}<span class="eyebrow">A POSSIBLE DIRECTION</span></div>${badge('待你确认','outline')}</div><h2 style="margin:17px 0 10px">为未来的创作，提前考虑显卡升级？</h2><p class="muted" style="font-size:14px;max-width:720px">${state.user==='creator-b'?'示例资料中，你提到本地创作受显存限制。是否仍要把它列为未来目标？':'这是一个可体验的方向示例。只有你确认确实有相应任务时，才应建立目标。'}</p><p class="caption" style="margin-top:10px">依据：示例任务陈述，而非浏览器历史或长期人格推断。</p><div class="row wrap" style="margin-top:22px">${btn('确认这个方向 '+icon('arrow','sm'),'new-goal','primary sm','data-template="gpu"')}${btn('还不确定','proposal-later','sm')}${btn('这不是我的需求','dismiss-proposal','sm')}${btn('依据不准确','proposal-evidence','sm')}</div></section>`:''}<div class="section-head"><h2>正在关注的方向 <span class="muted" style="font-size:15px">${active.length}</span></h2></div>${active.length?`<div class="grid-2 section">${active.map(goalCard).join('')}</div>`:empty('先从一个方向开始','不需要现在就选好型号。写下你想完成的事，或者现有物品遇到的问题。',btn('自己建立目标','new-goal','primary sm'))}${archived.length?`<section style="margin-top:30px"><h3>已归档的方向</h3>${archived.map(g=>`<div class="list-row"><div class="grow"><h4>${e(g.title)}</h4><p>不再关注，旧记录仍保留。</p></div>${btn('重新启用','restore-goal','sm',`data-id="${g.id}"`)}</div>`).join('')}</section>`:''}`;}
function goalCard(g){const f=funding(g);return `<article class="goal-card"><div class="between">${badge(g.status==='confirmed'?'方向已确认':'规划中','green')}${icon('compass','green')}</div><h3>${e(g.title)}</h3><p class="caption">${e(g.priority||'优先级待确认')} · 尚未锁定具体型号</p><div class="goal-meta"><div><small>计划目标</small><strong>${hk(g.target)}</strong></div><div><small>已预留</small><strong>${hk(g.reserved)}</strong></div><div><small>时间窗口</small><strong>${g.months||'—'} 个月</strong></div></div><div class="progress"><span style="width:${f.progress}%"></span></div><p class="caption" style="margin-top:10px">${g.target?`准备进度 ${Math.round(f.progress)}%`:'金额尚未确认'} · 计划不是账户余额</p><div class="card-bottom">${link('查看目标 '+icon('arrow','sm'),'/needs/'+g.id,'text-btn')}${btn('调整计划','edit-goal','sm',`data-id="${g.id}"`)}${btn('分析这项计划','ai-plan-select','sm',`data-plan="goal/${e(g.id)}"`)}</div></article>`;}
function goalDetail(id){const g=state.goals.find(x=>x.id===id);if(!g)return notFound();const f=funding(g);return `${heading(e(g.title),'方向已经确认，具体型号仍可改变。',btn('调整目标','edit-goal','',`data-id="${id}"`))}<div class="goal-hero section"><section class="panel"><div class="between">${badge('未来需求 · 用户确认','green')}${badge(e(g.priority||'优先级待确认'))}</div><h3 style="margin-top:24px">为什么可能需要</h3><p class="muted" style="margin-top:9px">${e(g.purpose)}</p><div class="divider" style="margin:22px 0"></div><h3>先确认能力，再选择型号</h3><p class="caption" style="margin-top:9px">${e(g.requirements||'最低性能与替代方案待补充。')}</p><div class="number-summary"><div><span class="caption">计划目标</span><strong>${hk(g.target)}</strong></div><div><span class="caption">已预留</span><strong>${hk(g.reserved)}</strong></div><div><span class="caption">准备差额</span><strong>${hk(f.gap)}</strong></div></div><div class="progress"><span style="width:${f.progress}%"></span></div><p class="caption" style="margin-top:12px">${g.monthly?`计划每月准备 ${hk(g.monthly)}，按此安排约需 ${f.months} 个月。`:'尚未填写每月准备计划。'}未来准备的金额不计作当前资金。</p>${link('查看整体计划 '+icon('arrow','sm'),'/plans','text-btn')}</section><section class="panel"><div class="art">${art('gpu')}</div><h3>现在需要核对什么</h3><ul class="step-list"><li><span class="step-index">1</span><div><h4>实际任务与显存需求</h4><p>用你计划运行的任务确认，不因新品出现就升级。</p></div></li><li><span class="step-index">2</span><div><h4>整机与额外成本</h4><p>电源、机箱、散热和兼容性也要纳入计划。</p></div></li><li><span class="step-index">3</span><div><h4>具体版本与报价</h4><p>没有核实资料前，保持候选状态。</p></div></li></ul></section></div><section class="section"><div class="section-head"><h2>可进一步检查的候选</h2><p class="caption">以下是方向示例，不是实时市场推荐或报价。</p></div><div class="teaser-row"><div class="row">${miniProduct(products['gpu-5090'])}<div><h3>RTX 5090 候选</h3><p>品牌版本、地区、保修与价格待核实；无需现在锁定它。</p></div></div>${btn('核对候选 '+icon('arrow','sm'),'confirm-product','', 'data-id="gpu-5090"')}</div></section><div class="row wrap">${btn('我已不再需要','archive-goal','',`data-id="${id}"`)}${link('返回未来需求','/needs','text-btn')}</div>`;}
function legacyPlans(){const active=state.goals.filter(g=>g.status!=='archived'),sum=active.reduce((s,g)=>s+Number(g.reserved||0),0),target=active.reduce((s,g)=>s+Number(g.target||0),0);return `${heading('我的计划','每一笔预留，都有自己的用途。金额由你填写，未来计划与当前预留分开。',btn(icon('plus')+' 新建目标','new-goal','primary'))}<section class="panel section"><div class="between"><h3>长期目标准备</h3>${badge('手动确认 · 非银行余额','outline')}</div><div class="number-summary"><div><span class="caption">目标金额合计</span><strong>${hk(target)}</strong></div><div><span class="caption">已分配预留</span><strong>${hk(sum)}</strong></div><div><span class="caption">尚待准备</span><strong>${hk(Math.max(0,target-sum))}</strong></div></div><p class="hint">这是各项目计划合计，不代表你的总资产。同一笔预留不应重复分配给多个目标。</p>${btn('核对可分配总额','allocation','sm')}</section><section class="section"><div class="section-head"><h2>目标优先顺序</h2><p class="caption">调整计划前，先看会影响哪一个目标。</p></div>${active.length?active.map((g,i)=>`<div class="priority-row"><span class="priority-num">${String(i+1).padStart(2,'0')}</span><div class="grow"><h3>${e(g.title)}</h3><p class="caption" style="margin-top:5px">${e(g.priority)} · 计划 ${hk(g.target)} · 已预留 ${hk(g.reserved)}</p><div class="progress" style="max-width:600px;margin-top:13px"><span style="width:${funding(g).progress}%"></span></div></div>${btn('调整','edit-goal','sm',`data-id="${g.id}"`)}</div>`).join(''):empty('还没有长期资金目标','先确认未来用途，再决定为它准备多少。',link('看看未来需求','/needs','btn sm'))}</section><section class="panel"><div class="between"><div><h3>一笔眼前的购买</h3><p class="caption" style="margin-top:7px">耳机的本次计划与显卡的长期预留分别记录，不能混作同一笔资金。</p></div>${link('查看耳机安排 '+icon('arrow','sm'),'/products/earbud-aster#plan','text-btn')}</div></section>`;}
function chart(p){if(p.id!=='earbud-aster'||p.variantChanged)return `<div style="padding:35px 15px">${empty('价格历史尚未建立','当前没有可核查的历史报价。你可以先确认型号，或设置等待新证据的条件。',btn('设置观察条件','watch-settings','sm',`data-id="${p.id}"`))}</div>`;const all=state.priceDropped?[...history,{date:'2026-10-15',price:429}]:history;const data=ui.range===30?all.filter(x=>x.date>='2026-09-15'):all;const min=state.priceDropped?400:460,max=620,W=650,H=220;const x=i=>48+i/Math.max(1,data.length-1)*(W-68),y=v=>18+(max-v)/(max-min)*165;const target=state.watch.find(w=>w.productId===p.id)?.target;return `<div class="chart-wrap"><div class="chart-tooltip" id="chart-tooltip" hidden></div><svg class="price-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="示例商品价格历史曲线，可聚焦每个点查看记录">${[max-20,Math.round((min+max)/2),min+20].map(n=>`<line x1="48" x2="632" y1="${y(n)}" y2="${y(n)}" stroke="#E0E5DC" stroke-width="1"/><text x="35" y="${y(n)+4}" text-anchor="end">${n}</text>`).join('')}${target&&target>=min&&target<=max?`<line x1="48" x2="632" y1="${y(target)}" y2="${y(target)}" stroke="#A56D48" stroke-dasharray="5 5"/><text x="630" y="${y(target)-7}" text-anchor="end">目标 ${target}</text>`:''}<path d="${data.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v.price)}`).join(' ')}" fill="none" stroke="#167A68" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${data.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v.price)}" r="${i===data.length-1?5:9}" fill="${i===data.length-1?'#167A68':'transparent'}" tabindex="0" role="button" aria-label="${v.date} 示例报价${v.price}，查看条件" data-chart-date="${v.date}" data-chart-price="${v.price}" data-action="price-point"/>`).join('')}<text x="48" y="211">${data[0]?.date.slice(5)}</text><text x="340" y="211" text-anchor="middle">示例记录</text><text x="632" y="211" text-anchor="end">${data.at(-1)?.date.slice(5)}</text></svg></div>`;}
function priceSection(p){const price=priceFor(state,p),fit=budgetFit(p.budget,price);return `<section id="price" class="section"><div class="price-layout"><div class="panel price-panel"><div class="price-top"><div><h3>价格记录</h3>${amount(price,'green')}<p class="price-change">${p.id==='earbud-aster'?`商家展示价 HK$899 · 非已核实的正常售价`:'当前候选 · 历史报价待核实'}</p></div><div class="price-range" aria-label="价格时间范围">${[30,90,365].map(n=>`<button class="range-btn ${ui.range===n?'active':''}" data-action="range" data-value="${n}" ${n===365?'disabled title="当前示例只覆盖90日"':''}>${n}日</button>`).join('')}</div></div>${chart(p)}<div class="chart-caption"><span>${p.importRecord?'来源：用户确认的导入记录，非平台官方实时报价':'来源：示例报价，未连接实时商家'}</span><span>${p.importRecord?'记录于 '+e(p.importRecord.identifiedAt?.slice(0,10)||'本次导入'):'截至 '+(state.priceDropped?'2026-10-15':'2026-10-14')}</span></div></div><aside class="panel budget-panel"><h3>我的购买安排</h3><div><p class="caption">本次计划金额</p>${amount(p.budget)}</div><div class="remainder"><p class="caption">${!fit.known?'财务条件未确认':fit.over?'超出本次计划':'按此报价购买后，计划内余'}</p>${amount(fit.known?(fit.over?fit.over:fit.remainder):null,fit.over?'negative':'green')}</div><p class="caption" style="margin:8px 0 12px">计划内，也不等于一定值得买。</p>${btn('调整我的计划 '+icon('arrow','sm'),'edit-product','text-btn',`data-id="${p.id}" data-focus="budget"`)}</aside></div><div class="window-note">${icon('clock')}<div><h4>购买窗口建议</h4><p>${price==null?'先核实型号、完整成本和实际用途。':fit.over?'当前报价超出你确认的计划，先检查是否愿意调整其他目标。':!fit.known?'价格资料和个人计划还不完整，暂不能判断财务适配。':'报价处于你填写的金额范围，仍需核实用途与质量。'}</p><p class="caption">这是当前条件下的观察建议，不是对未来最低价的预测。</p></div></div></section>`;}
function platformSection(p){if(p.id!=='earbud-aster'||p.variantChanged)return `<section class="section"><div class="section-head"><h2>平台与配置</h2><p class="caption">有可比的具体报价后，再开始比价。</p></div><div class="panel"><p class="muted">${p.importRecord?'已关联导入的商品链接；当前仅有一条记录，尚不能生成多平台实时对照。':p.price==null?'当前候选没有核实报价，请补充品牌版本和来源。':'当前只有用户填写的示例报价，未绑定真实商家。'}</p>${btn('补充商品资料','edit-product','text-btn',`data-id="${p.id}"`)}</div></section>`;return `<section class="section"><div class="section-head between"><div><h2>平台条件对照</h2><p class="caption">先对齐型号，再比较运费、保修与到手价。</p></div>${btn('如何比较 '+icon('info','sm'),'compare-help','text-btn')}</div><div class="panel" style="padding:0"><div class="table-scroll"><table class="offers-table"><thead><tr><th>平台 / 条件</th><th>到手价</th><th>运费</th><th>保修</th><th>选择</th><th>来源</th></tr></thead><tbody>${offers.map(o=>{const sum=state.priceDropped&&o.id==='a'?429:total(o);return `<tr class="${state.selectedOffer===o.id?'selected':''}"><td><strong style="font-weight:500">${o.merchant}</strong><div class="caption">${o.condition}</div></td><td class="offer-price">${hk(sum)}${o.id==='b'?'<div class="caption">479 + 40 运费</div>':''}</td><td>${o.shipping?hk(o.shipping):'已包含'}</td><td>${o.warranty}</td><td><button class="offer-select" data-action="select-offer" data-id="${o.id}">${state.selectedOffer===o.id?'已选 ✓':'选择'}</button></td><td>${btn(icon('external','sm'),'offer-source','text-btn',`data-id="${o.id}" aria-label="查看${o.merchant}的报价条件"`)}</td></tr>`;}).join('')}</tbody></table></div></div></section>`;}
function reviewSection(p){const items=reviews.filter(r=>ui.review==='all'||r.kind===ui.review);return `<section id="reviews" class="section"><div class="section-head between"><div><h2>质量与评价</h2><p class="caption">商品表现与商家服务分开看，也保留相反的声音。</p></div><div class="tabs"><button class="tab ${ui.review==='all'?'active':''}" data-action="review-filter" data-value="all">全部</button><button class="tab ${ui.review==='positive'?'active':''}" data-action="review-filter" data-value="positive">正向</button><button class="tab ${ui.review==='negative'?'active':''}" data-action="review-filter" data-value="negative">反向</button></div></div>${p.id==='earbud-aster'&&!p.variantChanged?`<div class="grid-3">${items.map(r=>`<article class="review-card"><div class="review-head"><span class="review-icon ${r.kind==='negative'?'negative':''}">${icon(r.kind==='positive'?'check':r.kind==='negative'?'info':'shield','sm')}</span>${badge(r.label,r.kind==='positive'?'green':r.kind==='negative'?'amber':'')}<span class="caption">${r.scope}</span></div><h3>${r.title}</h3><p>${r.body}</p><div class="review-source"><span>示例主题 · ${r.version}</span>${btn('展开 '+icon('arrow','sm'),'review-detail','text-btn',`data-id="${r.id}"`)}</div></article>`).join('')}</div>`:`<div class="note-banner">${icon('info')}<span>当前没有已核实的评价来源。${p.id==='stand-mini'?'可以先确认是否有新的用途。':'请先核实实际任务、版本和兼容性。'}观点卡会保留这一资料缺口。</span></div>`}</section>`;}
function viewpointCard(v,i,p){return `<article class="viewpoint ${v.color==='green'?'green-tone':v.color}" id="view-${v.key}"><div class="viewpoint-header"><span class="viewpoint-mark">${icon(v.icon,'lg')}</span><div class="viewpoint-name"><h3>${v.name} <button class="info-dot" data-action="v2-agent-help" data-key="${v.key}" aria-label="了解${v.name}">ⓘ</button></h3><div class="en">${v.en}</div></div><span class="viewpoint-number">0${i+1}</span></div><span class="status">${v.status}</span><h4>${e(v.headline)}</h4><blockquote>“${e(v.quote)}”</blockquote><p class="evidence">已知依据 · ${e(v.source)}</p><p class="question">待核实 · ${e(v.question)}</p><div class="viewpoint-footer"><button class="text-btn" data-action="evidence" data-target="${v.target}" data-id="${p.id}">${v.action} ${icon('arrow','sm')}</button><button class="text-btn correct" data-action="correct-view" data-id="${p.id}" data-key="${v.key}">不符合我的想法</button></div></article>`;}
function productPage(id){const p=product(state,id);if(!p)return notFound();const price=priceFor(state,p),fit=budgetFit(p.budget,price),vs=perspectives(p,price);return `<header id="overview" class="product-title"><div class="mini-art large">${art(p.art)}</div><div><p class="eyebrow">${e(p.category)} / DECISION STUDIO</p><h1 style="margin-top:5px">${e(p.name)}</h1><p class="subtitle">${e(p.configuration)} · ${e(p.tag||'当前购买')}</p></div><div class="product-tools">${badge(p.importRecord?'导入记录 · 非官方实时数据':'示例数据','outline')}${btn(icon('edit','sm')+' 修改资料','edit-product','sm',`data-id="${id}"`)}</div></header><nav class="product-nav" aria-label="商品区块">${[['overview','概览'],['price','价格与平台'],['reviews','质量与评价'],['plan','我的计划'],['perspectives','四个我'],['decision','决定']].map(([k,v])=>`<a href="#${k}" data-scroll="${k}">${v}</a>`).join('')}</nav><div class="path-fork"><button class="path-btn" data-scroll="price">${icon('search')} 核对商品证据 ${badge(p.price==null?'待补充':'已载入示例')}</button><button class="path-btn" data-scroll="plan">${icon('wallet')} 确认我的理由 ${badge(p.budget==null?'计划待确认':'已填写计划')}</button><span class="caption">两条路径，在四个我汇合。</span></div>${p.importRecord?`<section class="source-card"><h3>来自 ${e(p.category)} 的商品记录</h3><p>商品编号 ${e(p.importRecord.productId)} · 原币记录：${e(p.importRecord.currency||'币种待核实')} ${e(p.importRecord.originalPrice||'金额待核实')}。</p><p class="caption">AI 辅助提取、由你确认保存；未由平台官方接口核实。未确认港币金额时，预算适配保持未知。</p><a href="${e(p.sourceUrl)}" target="_blank" rel="noopener noreferrer" class="text-btn">打开商品原页 ↗</a></section>`:''}${priceSection(p)}${platformSection(p)}${reviewSection(p)}<section id="plan" class="section"><div class="section-head between"><div><h2>我的购买理由</h2><p class="caption">由你填写，可以修改。它们不是系统推断出来的性格。</p></div>${btn('编辑 '+icon('edit','sm'),'edit-product','text-btn',`data-id="${id}"`)}</div><div class="panel plan-summary"><div><h4>想解决的问题</h4><p>${e(p.purpose)}</p><p class="caption" style="margin-top:8px">${e(p.existing)}</p></div><div><h4>期待的体验</h4><p>${e(p.emotion||'暂未填写')}</p><p class="caption" style="margin-top:8px">喜欢与快乐也可以是价值。</p></div><div><h4>本次金额安排</h4><p>${p.budget==null?'尚未确认':hk(p.budget)}</p><p class="caption" style="margin-top:8px">${!fit.known?'需要更多资料才能判断':fit.over?`超出计划 ${hk(fit.over)}`:`购后计划内余 ${hk(fit.remainder)}`}，不代表银行余额。</p></div></div></section>${aiPanel('product',id)}<section id="perspectives" class="section"><div class="section-head between"><div><h2>四个我怎么看</h2><p class="caption">四种感知价值视角，把彼此矛盾的理由说清楚。</p></div>${btn('使用说明 ⓘ','v2-help','sm')} ${btn(icon('compass','sm')+' 换个情境看看','scenario','sm',`data-id="${id}"`)}</div><div class="grid-2">${vs.map((v,i)=>viewpointCard(v,i,p)).join('')}</div><div class="discussion-summary"><div><h4>共同认可</h4><p>${price==null?'先核实商品与价格资料，再判断是否适合。':'价格、体验和用途都值得考虑，便宜只是其中一项。'}</p></div><div><h4>分歧在哪里</h4><p>${p.id==='stand-mini'?'价格有吸引力，但你还没有新的使用场景。':fit.over?'情感期待仍成立，但这次金额超出了原计划。':'计划可能容纳这笔钱，使用与质量证据却还需核实。'}</p></div><div><h4>仍待核实</h4><p>核对现有物品、实际用途与商家条件。${btn('返回商品证据 '+icon('arrow','sm'),'scroll-evidence','text-btn')}</p></div></div></section><section id="decision" class="section"><div class="decision-panel"><div class="eyebrow">THE DECISION IS YOURS</div><h2 style="margin-top:9px">现在，怎样选择更适合你？</h2><p class="caption" style="margin-top:8px">保存你的理由。以后信息变了，也能看见当时为什么这样想。</p><div class="decision-options">${[['BUY','决定购买','用途与条件足够明确'],['WAIT','继续观察','等价格，或先补一条证据'],['SKIP','这次跳过','把钱和注意力留给别处']].map(([c,t,s])=>`<button class="decision-option" data-action="decide" data-choice="${c}" data-id="${id}"><span class="decision-word">${c}</span><span><strong style="font-size:14px;font-weight:500">${t}</strong><small style="display:block;margin-top:4px">${s}</small></span></button>`).join('')}</div><p class="decision-legend">${icon('shield','sm')} 系统保存依据，不替你购买。假设情境也不会改写真实决定。</p></div></section><footer class="product-footer"><span>报价、评价主题与陈述均为示例，未连接实时平台。</span>${link('查看资料如何使用 '+icon('arrow','sm'),'/settings?tab=connected','text-btn')}</footer>`;}
function newProduct(){const draft=ui.importDraft||{};return `${heading('检查一件商品','粘贴淘宝、京东或亚马逊的完整商品链接，先识别，再核对。',btn('平台连接说明','commerce-connections','sm'))}<div class="dashboard-grid"><section class="panel"><div class="between"><h3>AI 商品识别</h3>${badge('Poe · 按需调用','green')}</div><p class="caption" style="margin:14px 0">点击识别后，仅将公开页面字段与下方描述发送至 Poe。平台原页打不开时，可以复制标题、型号与价格原文；不会读取你的账号与订单。</p><form id="product-add-form">${field('url','完整商品链接',draft.url||'','text','支持淘宝／天猫、京东、亚马逊；短链接请先打开后复制地址栏。','placeholder="https://…" maxlength="3000"')}${textarea('description','补充商品描述／分享文案（可选）',draft.text||'','可粘贴：商品标题、准确型号、选中配置、价格与明确币种（HKD/CNY/USD）。不需要提供订单号或个人资料。')}${field('productName','或者仅手动输入商品名称','','text','','placeholder="例如：通勤耳机"')}<div id="add-error" class="field-error" role="alert">${uiEscape(commerce.error||'')}</div><div class="row wrap" style="margin-top:16px">${commerce.active?btn('取消识别','commerce-cancel','sm'):'<button class="btn primary" type="submit">识别并核对商品</button>'}${btn('连接 AI','ai-connect','sm')}${btn('手动填写','commerce-manual','text-btn')}</div><p class="caption" role="status" aria-live="polite" style="margin-top:12px">${commerce.active?'正在读取公开资料并提取商品字段…':commerce.result?'识别结果已返回，核对后再加入商品。':'公开页面与粘贴描述均需核对；未连接平台官方报价与评价接口。'}</p>${commerce.result?btn('打开识别结果','commerce-preview','sm'):''}</form></section><section><div class="source-card"><h3>三个平台，同一个核对流程</h3><p>链接编号 → 公开字段／补充描述 → AI 提取 → 确认型号、配置与币种 → 加入购买分析。</p><p class="caption">不同币种不会直接计入港币预算；不同版本不会自动认作同款。</p></div><div class="section-head"><h3>也可以先检查一个示例</h3><p class="caption">以下为独立示例，报价不是实时市场数据。</p></div>${Object.values(products).map(p=>`<div class="list-row">${miniProduct(p)}<div class="grow"><h3>${p.name}</h3><p>${p.configuration}</p></div>${btn(icon('arrow'),'confirm-product','icon-btn',`data-id="${p.id}" aria-label="确认${p.name}型号"`)}</div>`).join('')}</section></div>`;}

function watchlist(){return `${heading('观察清单','价格到了、资料补齐了，再回来重评。提醒不会替你下单。',link(icon('plus')+' 添加商品','/products/new','btn primary'))}<section class="section"><div class="section-head"><h2>具体商品 <span style="font-size:14px;color:var(--muted)">${state.watch.length}</span></h2></div>${state.watch.length?state.watch.map(w=>{const p=product(state,w.productId);if(!p)return '';return `<div class="panel section"><div class="between"><div class="row">${miniProduct(p)}<div><h3>${e(p.name)}</h3><p class="caption">${w.enabled?'正在观察':'已暂停提醒'} · ${w.target?`目标 ${hk(w.target)}`:'等待新证据'}</p></div></div>${badge(state.decisions.find(d=>d.productId===p.id)?.choice==='WAIT'?'WAIT':'观察中','amber')}</div><p class="muted" style="font-size:13px;margin:18px 0">${e(w.note)}</p><div class="row wrap">${link('重新评估 '+icon('arrow','sm'),'/products/'+p.id+'#perspectives','btn sm')}${btn('观察条件','watch-settings','sm',`data-id="${p.id}"`)}${btn(w.enabled?'暂停提醒':'恢复提醒','toggle-watch','text-btn',`data-id="${p.id}"`)}</div></div>`;}).join(''):empty('没有需要等待的商品','检查商品后选择 WAIT，就能设定价格或新证据的观察条件。',link('检查商品','/products/new','btn sm'))}</section><section class="section"><div class="section-head"><h2>关注的方向</h2><p class="caption">方向关注看候选；具体价格提醒必须绑定型号。</p></div>${state.goals.filter(g=>g.status!=='archived').length?`<div class="grid-2">${state.goals.filter(g=>g.status!=='archived').map(goalCard).join('')}</div>`:link('先建立一个未来目标 '+icon('arrow','sm'),'/needs','text-btn')}</section>`;}
function decisionRow(d,compact=false){const p=d.snapshot.product;return `<article class="history-item">${miniProduct(p)}<div class="grow"><h3>${e(p.name)}</h3><p class="reason">${e(d.reason)}</p><p class="caption" style="margin-top:6px">${hk(d.snapshot.price)} · ${d.purchased?'用户确认已下单':d.choice==='BUY'?'决定购买，未确认下单':'当时的决定'}</p></div><div class="history-meta">${badge(d.choice,d.choice==='WAIT'?'amber':'green')}<div class="date">${new Date(d.createdAt).toLocaleDateString('zh-CN')}</div>${link(compact?'查看':'查看决定 '+icon('arrow','sm'),'/decisions/'+d.id,'text-btn')}</div></article>`;}
function decisions(){const ds=state.decisions.filter(d=>ui.filter==='all'||d.choice===ui.filter);return `${heading('决策档案','留住当时的价格与理由。改变想法，也不必抹掉过去。',link('检查商品','/products/new','btn'))}<div class="decision-filter">${['all','BUY','WAIT','SKIP'].map(v=>`<button class="tab ${ui.filter===v?'active':''}" data-action="decision-filter" data-value="${v}">${v==='all'?'所有决定':v}</button>`).join('')}</div>${ds.length?ds.map(d=>decisionRow(d)).join(''):empty('这里还没有决定','保存一笔购买的 BUY、WAIT 或 SKIP，留下你自己的理由。',link('开始检查','/products/new','btn primary sm'))}`;}
function decisionDetail(id){const d=state.decisions.find(d=>d.id===id);if(!d)return notFound();const s=d.snapshot,p=s.product,versions=state.decisions.filter(x=>x.productId===p.id),events=state.changes.filter(c=>c.decisionId===id);return `${heading('当时，我为什么这样选','这是保存于 '+new Date(d.createdAt).toLocaleString('zh-CN')+' 的快照。新资料不会覆盖它。',link('返回档案','/decisions','btn'))}<div class="dashboard-grid section"><section class="panel"><div class="between"><div class="row">${miniProduct(p)}<div><h3>${e(p.name)}</h3><p class="caption">${e(p.configuration)}</p></div></div>${badge(d.choice,d.choice==='WAIT'?'amber':'green')}</div><div class="snapshot-top" style="margin-top:27px"><div><span class="caption">当时报价</span><strong>${hk(s.price)}</strong></div><div><span class="caption">当时计划</span><strong>${hk(s.budget)}</strong></div><div><span class="caption">购买状态</span><strong style="font-size:17px">${d.purchased?'用户确认已下单':d.choice==='BUY'?'尚未确认下单':d.choice==='WAIT'?'继续观察':'本次跳过'}</strong></div></div><div class="snapshot-reason"><span class="eyebrow">MY REASON</span><p>“${e(d.reason)}”</p></div><p class="caption">当时用途：${e(p.purpose)}</p><div class="row wrap" style="margin-top:21px">${link('用新资料重新评估 '+icon('arrow','sm'),'/products/'+p.id,'btn sm')}${btn('查看当时四个我','snapshot-views','sm',`data-id="${id}"`)}</div>${d.choice==='BUY'?`<div class="divider" style="margin:23px 0"></div>${d.purchased?`<p class="caption">支付 ${hk(d.paidAmount??s.price)} · ${e(d.purchasedAt||'日期未填')} · 用户主动确认</p>`:`<p class="caption" style="margin-bottom:13px">决定购买不等于订单完成。你实际下单了吗？</p><div class="row wrap">${btn('已下单','purchase-confirm','primary sm',`data-id="${id}"`)}${btn('还没买','not-purchased','sm')}${btn('改主意了','reconsider','text-btn',`data-id="${p.id}"`)}</div>`}`:''}</section><aside><div class="section-head"><h3>这个商品的决定时间线</h3></div><div class="timeline">${versions.map(v=>`<div class="timeline-item"><h4>${v.choice} · ${hk(v.snapshot.price)}</h4><p>${new Date(v.createdAt).toLocaleString('zh-CN')}</p>${link(v.id===id?'当前版本':'查看这个版本','/decisions/'+v.id,'text-btn')}</div>`).join('')}</div><p class="hint">${d.previousVersionId?'这次决定与上一版本关联。':'这是第一份已保存的决定。'}重新评估创建新版本，草稿变化不会改写快照。</p></aside></div><section class="section"><div class="section-head"><h2>下单后新发现</h2><p class="caption">同款降价与更适合的商品，是两种不同的信息。</p></div>${!d.purchased?`<div class="note-banner">${icon('info')}<span>先确认是否实际下单，才能记录针对该订单的新发现。</span></div>`:`<div class="demo-controls">${btn('载入同款降价示例','load-drop','',`data-id="${id}" ${p.id!=='earbud-aster'||p.variantChanged||s.offer!=='a'?'disabled':''}`)}${btn('添加更合适的商品','add-alternative','',`data-id="${id}"`)}</div><p class="caption">由你明确载入示例；未连接实时市场提醒。新报价情境日期为 2026-10-15。</p>`}${events.map(c=>`<div class="teaser-row" style="margin-top:18px"><div><h3>${c.kind==='price'?`${hk(c.oldPrice)} → ${hk(c.newPrice)}`:e(c.alternativeName)}</h3><p>${c.resolution?`你记录的处理：${e(c.resolution)}`:c.kind==='price'?'新的报价条件需要核对。':'先比较用途和质量，再看价格。'}</p></div>${link('查看 '+icon('arrow','sm'),'/changes/'+c.id,'btn sm')}</div>`).join('')}</section>`;}
function changePage(id){const c=state.changes.find(x=>x.id===id);if(!c)return notFound();const d=state.decisions.find(x=>x.id===c.decisionId),p=d.snapshot.product;return `${heading('处理下单后新发现','先对齐条件，再决定要不要处理。后来的变化，不会自动否定当时的选择。',link('查看原决定','/decisions/'+d.id,'btn'))}<div class="comparison"><section class="panel"><p class="eyebrow">THEN / 当时</p><h3 style="margin-top:16px">${e(p.name)}</h3>${amount(d.snapshot.price)}<p class="caption">原决定快照 · ${e(d.snapshot.observedAt)}</p><p style="font-size:13px;margin-top:17px">${e(d.reason)}</p></section><section class="panel new"><p class="eyebrow">NOW / 新发现</p><h3 style="margin-top:16px">${c.kind==='price'?'同款同配置的新报价':e(c.alternativeName)}</h3>${amount(c.newPrice??c.alternativePrice)}<p class="caption">${c.kind==='price'?'示例 A · 2026-10-15 · 同款条件需核对':'替代型号 · 用户手动补充'}</p><p style="font-size:13px;margin-top:17px">${c.kind==='price'?`报价差额 ${hk(c.oldPrice-c.newPrice)}，处理成本和价保条件尚未核实。`:e(c.alternativeReason)}</p></section></div><div class="grid-2 section"><section class="panel"><h3>先核对这些条件</h3><ul class="step-list">${(c.kind==='price'?['商品型号、配置与新旧状况一致吗？','运费、优惠和保修条件一致吗？','订单时间是否在商家的价保或退货范围？']:['它解决了原商品未解决的具体问题吗？','有质量和用途的证据，还是只是另一次心动？','更换会增加多少钱、时间和处理成本？']).map((s,i)=>`<li><span class="step-index">${i+1}</span><p>${s}</p></li>`).join('')}</ul>${btn('查看报价与平台规则 '+icon('external','sm'),'policy','text-btn')}</section><section class="panel"><h3>由你记录处理结果</h3><p class="caption" style="margin:8px 0 20px">此处记录你的行动，不会替你向平台提交申请。</p><form id="resolution-form" data-id="${id}"><div class="field"><label for="resolution">准备怎样处理</label><select id="resolution" name="resolution">${['尚未决定','保留订单','申请价保','取消订单','退货或更换'].map(v=>`<option ${c.resolution===v?'selected':''}>${v}</option>`).join('')}</select></div>${textarea('reason','为什么这样选',c.resolutionReason||'')}<button class="btn primary" type="submit">保存我的处理记录</button></form></section></div>`;}
function settings(){return `${heading('我的资料与设置','自己的陈述、提醒和记录，都可以由自己管理。')}${aiPanel('direction')}<div class="settings-nav">${[['profile','自我资料'],['notifications','提醒'],['data','数据管理'],['connected','未来数据接入']].map(([k,v])=>`<button class="tab ${ui.settings===k?'active':''}" data-action="settings-tab" data-value="${k}">${v}</button>`).join('')}</div><section class="panel" style="max-width:900px">${ui.settings==='profile'?`<h2>可编辑的自我模型</h2>${btn('职业、兴趣与安排','v2-basis','sm')}<p class="caption" style="margin:8px 0 25px">这里保存你确认的用途与偏好，不是长期人格诊断。</p><form id="profile-form">${field('name','称呼',state.profile.name)}${textarea('profileNote','我希望系统记住的购买原则',state.profile.note||'','每条系统归纳都应该允许你纠正。')}<p class="caption" style="margin-bottom:20px">资料来源：用户主动填写 · 四卡只引用已确认的本次陈述。</p><button class="btn primary" type="submit">保存资料</button></form><div class="divider" style="margin:25px 0"></div>${btn(icon('logout','sm')+' 退出示例账户','logout','')}`:ui.settings==='notifications'?`<h2>只提醒你确认过的事</h2>${[['direction','未来方向提议','与你主动填写的任务相关，由你确认后才建立目标。'],['price','商品价格与证据变化','仅针对已确认型号和设定条件的商品。'],['after','下单后的新发现','先确认已下单，再关注可比的新信息。']].map(([k,t,s])=>`<div class="toggle-row"><div><h3>${t}</h3><p>${s}</p></div><button class="switch ${state.notifications[k]?'on':''}" role="switch" aria-checked="${state.notifications[k]}" aria-label="${t}" data-action="toggle-notification" data-key="${k}"><span></span></button></div>`).join('')}<p class="hint" style="margin-top:22px">当前提醒是可交互的示例状态；没有后台实时抓取或通知服务。</p>`:ui.settings==='data'?`<h2>记录属于你</h2><p class="muted" style="font-size:14px;margin:13px 0 22px">示例业务资料保存在本浏览器。密码、银行资料和真实商家订单没有被收集。</p><div class="stack">${btn(icon('download')+' 导出当前目标与决定','export','')}${btn(icon('trash')+' 重置当前示例账户','reset','danger')}</div><p class="caption" style="margin-top:20px">重置前会再次提示；导出文件包含当前账户的目标、计划、陈述和决定版本。</p>`:`<div class="between wrap"><h2>Connected Self</h2>${badge('未来概念 · 当前未开放','amber')}</div><p class="muted" style="font-size:14px;margin:14px 0 24px">未来可以在用户逐项确认后，将选择的数据整理为可检查的购买事件和长期模式。当前没有连接按钮，也没有读取你的浏览器、社交或聊天资料。</p>${[['选择资料来源','浏览器历史、社交媒体或选定聊天记录分别选择。'],['限定范围','选择账户、时间与具体资料，不自动读取全部历史。'],['预览待导入内容','先查看具体内容和可能提取的购买事件。'],['确认候选事件与动机','用户逐条接受、修改或否认。'],['查看长期模式','说明依据和不确定性，不把推测当人格事实。'],['修改、撤回或删除','撤回后停止在后续讨论中引用。']].map(([t,s],i)=>`<div class="concept-step"><span class="num">0${i+1}</span><div><h3>${t}</h3><p>${s}</p></div></div>`).join('')}`}</section>`;}
function notFound(){return heading('这份记录暂时找不到','可以返回首页，继续检查商品或打开其他决定。',link('返回首页','/home','btn primary'));}
function toast(text){clearTimeout(toastTimer);const t=$('#toast');t.textContent=translateText(text);t.classList.add('visible');toastTimer=setTimeout(()=>t.classList.remove('visible'),4000);}
function closeDrawer(restore=true){drawerSource=null;$('#overlay-root').innerHTML='';document.body.style.overflow='';ui.scenario='actual';if(restore&&drawerReturn?.isConnected)drawerReturn.focus();}
function openDrawer(title,content,{wide=false,eyebrow='My Best Choice / DETAILS'}={}){drawerReturn=document.activeElement;drawerSource={title,content,wide,eyebrow};$('#overlay-root').innerHTML=localizeMarkup(`<div class="overlay" data-overlay><section class="drawer ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-head"><div><p class="eyebrow">${eyebrow}</p><h2 id="drawer-title">${title}</h2></div>${languageButton()}<button class="icon-btn" data-action="close-drawer" aria-label="关闭详情">${icon('close')}</button></header>${content}</section></div>`);document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.drawer .icon-btn')?.focus());}
function refresh(){const y=window.scrollY;render(false);window.scrollTo(0,y);}
function scrollToBlock(id){const n=document.getElementById(id);if(n){n.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});n.classList.remove('flash');requestAnimationFrame(()=>n.classList.add('flash'));}}
function goto(path){planPreview=null;closeDrawer(false);ui.mobile=false;historyPush(path);render();}
function historyPush(path){window.history.pushState({},'',path);}
function render(resetScroll=true){const path=location.pathname.replace(/\/$/,'')||'/',root=path.split('/')[1];const publicPaths=['/','/login','/signup','/recover'];if(!publicPaths.includes(path)&&!currentUser){sessionStorage.setItem(KEY+'-pending',location.pathname+location.search+location.hash);window.history.replaceState({},'','/');app.innerHTML=localizeMarkup(landing());syncLanguageShell();return;}
 let content='';if(path==='/')content=landing();else if(['/login','/signup','/recover'].includes(path))content=auth(path);else if(path==='/setup')content=setup();else{if(!state?.setup){sessionStorage.setItem(KEY+'-pending',location.pathname+location.search+location.hash);window.history.replaceState({},'','/setup');app.innerHTML=localizeMarkup(setup());syncLanguageShell();return;}const id=decodeURIComponent(path.split('/')[2]||'');if(root==='home')content=home();else if(root==='needs')content=id&&id!=='new'?goalDetail(id):needs();else if(root==='proposals')content=proposals();else if(root==='plans')content=id?goalDetail(id):plans();else if(root==='products')content=id==='new'?newProduct():productPage(id);else if(root==='watchlist')content=watchlist();else if(root==='decisions')content=id?decisionDetail(id):decisions();else if(root==='changes')content=changePage(id);else if(root==='settings'){const tab=new URLSearchParams(location.search).get('tab');if(tab)ui.settings=tab;content=settings();}else content=notFound();content=shell(content,path);}
 app.innerHTML=localizeMarkup(content);syncLanguageShell();document.title=translateText(paths[root]||'先想清楚，再购买')+' · My Best Choice';animatePlanNumbers();if(resetScroll)window.scrollTo(0,0);if(location.hash)requestAnimationFrame(()=>scrollToBlock(location.hash.slice(1)));}
function productEdit(id,key){const p=product(state,id);if(!p)return;openDrawer(key?'纠正这次的观点':'确认我的用途与计划',`<p class="body">这些是本次购买的用户陈述。保存后会更新当前讨论，不改写已保存的决定。</p><form id="product-edit-form" data-id="${id}">${field('purpose','想解决的问题',p.purpose)}${textarea('existing','现有物品与替代方案',p.existing)}${field('budget','本次计划金额 HK$',p.budget??'','number','不填写则显示财务条件未确认。','min="0" step="0.01"')}${textarea('emotion','我期待的体验',p.emotion)}${textarea('social','他人的推荐或形象是否影响我',p.social)}<div class="field-error" id="form-error"></div><div class="drawer-actions"><button type="submit" class="btn primary">保存并更新四个我</button>${btn('取消','close-drawer')}</div></form>`);if(key)requestAnimationFrame(()=>document.getElementById(key==='price'||key==='budget'?'budget':key==='use'?'existing':key==='emotion'?'emotion':'social')?.focus());}
function goalForm(id,template){const existing=id?state.goals.find(g=>g.id===id):template?state.goals.find(g=>g.title.includes('显卡')&&g.status!=='archived'):null;const g=existing||{title:template?'升级适合本地 AI 创作的显卡':'',purpose:template?'本地创作任务受显存限制，想提前准备升级':'',requirements:'',months:12,priority:'重要但不急',target:null,reserved:0,monthly:0};openDrawer(existing?'调整目标与准备计划':'建立一个未来目标',`<p class="body">先确认用途，再安排时间和资金。计划目标不是商品的真实市场报价。</p><form id="goal-form" data-id="${existing?.id||''}">${field('title','未来可能需要的方向',g.title,'text','','required placeholder="例如：升级适合创作的显卡"')}${textarea('purpose','为什么需要',g.purpose)}${textarea('requirements','最低条件与待核实问题',g.requirements,'也可以写下目前还有什么可用的替代方案。')}<div class="grid-2">${field('months','预计几个月后需要',g.months,'number','','min="1" max="120" required')}${field('target','计划目标金额 HK$',g.target??'','number','可暂不填写','min="0" step="1"')}</div><div class="grid-2">${field('reserved','已经预留 HK$',g.reserved,'number','','min="0" required')}${field('monthly','未来每月计划准备 HK$',g.monthly,'number','不算作目前已有资金','min="0"')}</div><div class="field"><label for="priority">优先程度</label><select id="priority" name="priority">${['重要且近期需要','重要但不急','只是感兴趣'].map(v=>`<option ${g.priority===v?'selected':''}>${v}</option>`).join('')}</select></div><p class="caption">保存后，候选商品仍需核型、核价和质量评估。若设置过可分配总额，不能重复分配超过它。</p><div class="field-error" id="form-error"></div><div class="drawer-actions"><button class="btn primary" type="submit">${existing?'保存调整':'确认并建立目标'}</button>${btn('先不建立','close-drawer')}</div></form>`);}
function confirmProduct(id){const p=product(state,id);if(!p)return;openDrawer('先确认是同一件商品',`<div class="row" style="margin-bottom:22px">${miniProduct(p)}<div><h3>${e(p.name)}</h3><p class="caption">${e(p.model)}</p></div></div><form id="confirm-product-form" data-id="${id}"><div class="field"><label for="configuration">型号与配置</label><select id="configuration" name="configuration"><option value="same">${e(products[id]?.configuration||p.configuration)}</option><option value="other">其他版本／地区／保修，暂未确认</option></select></div><p class="hint">不同配置的价格不会混在一条曲线上。选择其他版本后，跨平台与历史数据会标为待核实。</p><div class="drawer-actions"><button class="btn primary" type="submit">确认，开始检查</button>${btn('取消','close-drawer')}</div></form>`);}
function watchForm(id){const p=product(state,id),w=state.watch.find(x=>x.productId===id);openDrawer('设置观察条件',`<p class="body">${e(p.name)}。条件满足时只提示重新评估，不自动购买。</p><form id="watch-form" data-id="${id}">${field('target','目标到手价 HK$',w?.target??'','number','可以不设价格，改为等待用途或质量证据。','min="0" step="1"')}${textarea('note','还想核实什么',w?.note||'先确认用途与商家条件')}<label class="check-row"><input type="checkbox" name="enabled" ${w?.enabled===false?'':'checked'}>开启该商品的示例观察提醒</label><div class="drawer-actions"><button class="btn primary" type="submit">保存观察条件</button>${btn('取消','close-drawer')}</div></form>`);}
function scenarioContent(p,s){const actual=priceFor(state,p),views=perspectives(p,actual,s);return `<div class="note-banner warn">${icon('compass')}<span>以下是假设，不会改写真实金额、商品资料或已保存决定。</span></div><div class="field" style="margin-top:23px"><label for="scenario">只改变一个条件</label><select id="scenario" data-scenario-id="${p.id}">${[['actual','原始情境'],['no-sale','没有折扣标签'],['price-up','价格上涨 10%'],['budget-down','本次计划缩减 25%'],['urgent','明天突然急需使用'],['unused','三个月后可能很少使用']].map(([k,v])=>`<option value="${k}" ${s===k?'selected':''}>${v}</option>`).join('')}</select></div><p class="caption">真实当前报价：${hk(actual)}；真实计划：${hk(p.budget)}。${s==='price-up'&&actual!=null?`本次假设报价 ${hk(Math.round(actual*1.1))}。`:s==='budget-down'&&p.budget!=null?`本次假设计划 ${hk(Math.round(p.budget*.75))}。`:''}</p>${views.map(v=>`<div class="scenario-card ${v.color==='green'?'green-tone':v.color}"><h4>${v.name} · ${v.status}</h4><p>${e(v.headline)}</p><blockquote>“${e(v.quote)}”</blockquote></div>`).join('')}<div class="drawer-actions">${btn('关闭，回到真实情境','close-drawer','primary')}</div>`;}
function decideForm(id,choice){const p=product(state,id),price=priceFor(state,p),fit=budgetFit(p.budget,price);const defaults={BUY:'我确认了用途，并愿意按当前资料和计划购买。',WAIT:'价格吸引我，但用途、质量或商家条件还需要确认。',SKIP:p.id==='stand-mini'?'已有两个可用支架，暂时没有新的使用场景。':'这次没有足够明确的用途，先保留资金和注意力。'};openDrawer('保存这次的 '+choice,`<p class="body">${e(p.name)} · 当前报价 ${hk(price)} · 用户计划 ${hk(p.budget)}。</p>${!fit.known||fit.over?`<div class="note-banner warn">${icon('info')}<span>${!fit.known?'价格或财务条件尚未确认。请把未知事项写进理由。':`超出本次计划 ${hk(fit.over)}。如果仍决定购买，请明确记录原因。`}</span></div>`:''}<form id="decision-form" data-id="${id}" data-choice="${choice}" style="margin-top:20px">${textarea('reason','用自己的话留下理由',defaults[choice])}${choice==='WAIT'?`${field('target','观察目标价 HK$','','number','可留空，改为等待新证据。','min="0"')}${textarea('condition','还需要什么变化','核实用途与通话质量，再重新评估。')}`:''}${choice==='SKIP'&&id==='gpu-5090'?'<label class="check-row"><input type="checkbox" name="keepGoal" checked>保留显卡升级方向，只跳过这个候选</label>':''}<p class="caption">将保存当时的价格、用途、计划、四个视角与未知事项。以后重新评估会创建新版本。</p><div class="field-error" id="form-error"></div><div class="drawer-actions"><button class="btn primary" type="submit">确认保存 ${choice}</button>${btn('继续核实','close-drawer')}</div></form>`);}
function sourceDrawer(type,id,extra={}){if(type==='review'){const r=reviews.find(x=>x.id===id);openDrawer(r.topic,`${badge(r.scope)}<p class="body">${r.body}</p><div class="source-card"><h4>来源情况</h4><p class="caption">示例评价主题，不是真实用户引语；没有真实样本数量、认证购买标记或外部原文。</p><p class="caption">适用版本：${r.version}。当前证据存在缺口。</p></div>${btn('暂无外部原文','none','', 'disabled')}<div class="drawer-actions">${btn('回到商品证据','close-drawer','primary')}</div>`);}else{const o=offers.find(x=>x.id===id)||offers[0];openDrawer(type==='point'?'一条价格记录':'报价条件与来源',`<p class="body">${type==='point'?`${e(extra.date)} 的示例记录为 ${hk(extra.price)}。`:e(o.merchant)+'：先看完整成本，再比较。'}</p><div class="source-card"><div class="numeric-row"><span>商品价格</span><strong>${hk(type==='point'?Number(extra.price):o.price)}</strong></div><div class="numeric-row"><span>运费</span><strong>${hk(o.shipping)}</strong></div><div class="numeric-row"><span>到手价</span><strong>${hk(type==='point'?Number(extra.price):total(o))}</strong></div><p class="caption">保修：${e(o.warranty)}；配置：${e(o.condition)}。这条记录仅用于展示信息结构。</p></div><p class="body">没有绑定真实商家和商品 URL，因此不伪造“前往购买”链接。接入真实数据后才启用来源跳转。</p>${btn('未绑定真实商家','none','', 'disabled')}`);}}
function purchaseForm(id){const d=state.decisions.find(x=>x.id===id);openDrawer('你实际下单了吗？',`<p class="body">由你主动确认；My Best Choice 没有读取外部商家订单。</p><form id="purchase-form" data-id="${id}">${field('paidAmount','实际支付 HK$',d.snapshot.price??'','number','可不填写；不要用未知价格代替实际支付。','min="0" step="0.01"')}${field('purchasedAt','下单日期','2026-10-14','date','当前为示例情境日期。')}<div class="drawer-actions"><button class="btn primary" type="submit">确认已下单</button>${btn('还没买','close-drawer')}</div></form>`);}
function alternativeForm(id){openDrawer('记录更合适的候选',`<p class="body">先说它解决了什么问题。不同型号不直接作为同款降价。</p><form id="alternative-form" data-id="${id}">${field('name','候选商品名称','','text','','required placeholder="例如：通话更适合的型号"')}${field('price','候选报价 HK$','','number','没有核实报价可以不填。','min="0"')}${textarea('reason','它为什么可能更合适','','把用途、质量证据和未知事项分别写清楚。')}<div class="drawer-actions"><button class="btn primary" type="submit">保存这条新发现</button>${btn('取消','close-drawer')}</div></form>`);}
function finishSetup(){state.setup=true;persist();const next=sessionStorage.getItem(KEY+'-pending');sessionStorage.removeItem(KEY+'-pending');goto(next&&next!='/setup'?next:'/home');}
function manualProduct(name='',url=''){openDrawer('手动补充商品资料',`<p class="body">手动填写同样可以开始检查。请确认名称与版本；未知价格可以留空。</p><form id="manual-product-form">${field('name','商品名称',name,'text','','required')}${field('model','型号','','text','','required')}${field('configuration','配置与保修','','text','','required')}${field('price','已核实报价 HK$','','number','','min="0"')}${field('url','来源链接',url,'url')}<button class="btn primary" type="submit">保存并核对</button></form>`);}
document.addEventListener('click',ev=>{const nav=ev.target.closest('[data-nav]');if(nav){ev.preventDefault();goto(nav.getAttribute('href'));return;}const sc=ev.target.closest('[data-scroll]');if(sc){ev.preventDefault();scrollToBlock(sc.dataset.scroll);return;}if(ev.target.hasAttribute('data-overlay')){closeDrawer();return;}const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;ev.preventDefault();const {action:a,id,key,value,target}=el.dataset;
 if(a==='login'){currentUser=el.dataset.user;sessionStorage.setItem(KEY+'-user',currentUser);load();ui.setupStep=0;if(new URLSearchParams(location.search).get('next')==='needs')sessionStorage.setItem(KEY+'-pending','/needs');goto(state.setup?sessionStorage.getItem(KEY+'-pending')||'/home':'/setup');}
 else if(a==='close-drawer')closeDrawer();else if(a==='setup-back'){ui.setupStep--;render();}else if(a==='setup-skip'){ui.setupStep=2;render();}
 else if(a==='mobile-open'||a==='mobile-close'){ui.mobile=a==='mobile-open';refresh();}
 else if(a==='new-goal')goalForm(null,el.dataset.template);else if(a==='edit-goal')goalForm(id);else if(a==='proposal-later'){toast('保留提议，准备好后再确认。');}else if(a==='dismiss-proposal'){state.dismissedProposal=true;persist();refresh();}
 else if(a==='proposal-evidence')openDrawer('这条提议从哪里来',`<p class="body">这是基于“本地创作任务受显存限制”的演示提议，不是对浏览器记录或长期人格的推断。确认用途、最低条件和时间后才建立目标。</p>${btn('建立前先修改','new-goal','primary','data-template="gpu"')}`);
 else if(a==='archive-goal'||a==='restore-goal'){const g=state.goals.find(x=>x.id===id);if(g){const status=a==='archive-goal'?'archived':'planning';if(status==='planning'&&!validatePlan(state,state.goals.map(x=>x.id===id?{...x,status}:x)).valid){toast('重新启用会超过可分配预留，请先调整计划。');return;}g.status=status;persist();goto('/needs');}}
 else if(a==='allocation')openDrawer('核对可分配预留',`<form id="allocation-form">${field('pool','当前可分配总额 HK$',state.reservedPool??'','number','仅使用你主动确认的金额，不代表银行余额。','min="0" required')}<div id="form-error" class="field-error"></div><button type="submit" class="btn primary">确认可分配总额</button></form>`);
 else if(a==='confirm-product')confirmProduct(id);else if(a==='edit-product'||a==='correct-view')productEdit(id,key);
 else if(a==='select-offer'){state.selectedOffer=id;persist();refresh();}else if(a==='range'){ui.range=Number(value);refresh();}
 else if(a==='review-filter'){ui.review=value;refresh();}else if(a==='review-detail')sourceDrawer('review',id);else if(a==='offer-source')sourceDrawer(state.priceDropped&&id==='a'?'point':'offer',id,{date:'2026-10-15',price:429});else if(a==='price-point')sourceDrawer('point','a',{date:el.dataset.chartDate,price:el.dataset.chartPrice});
 else if(a==='compare-help')openDrawer('比较的是完整条件',`<p class="body">示例 B 的 HK$479 加上 HK$40 运费，到手价为 HK$519；它的保修条件也不同。低标价不等于更合适。</p>${btn('明白，继续核对','close-drawer','primary')}`);
 else if(a==='evidence'){closeDrawer(false);scrollToBlock(target);}else if(a==='scroll-evidence')scrollToBlock('price');
 else if(a==='scenario'){ui.scenario='actual';openDrawer('换个情境看看',scenarioContent(product(state,id),'actual'));}
 else if(a==='decide')decideForm(id,el.dataset.choice);else if(a==='watch-settings')watchForm(id);else if(a==='toggle-watch'){const w=state.watch.find(x=>x.productId===id);if(w){w.enabled=!w.enabled;persist();refresh();}}
 else if(a==='decision-filter'){ui.filter=value;refresh();}else if(a==='snapshot-views'){const d=state.decisions.find(x=>x.id===id);openDrawer('当时的四个我',d.snapshot.perspectives.map(v=>`<div class="scenario-card"><h3>${e(v.name)}</h3><p>${e(v.headline)}</p><blockquote>${e(v.quote)}</blockquote></div>`).join(''));}
 else if(a==='purchase-confirm')purchaseForm(id);else if(a==='not-purchased')toast('保留购买意向，未记为已下单。');else if(a==='reconsider')goto('/products/'+id);
 else if(a==='load-drop'){const c=triggerDrop(state,id);if(c){persist();goto('/changes/'+c.id);}else toast('请先确认同款商品已实际下单。');}else if(a==='add-alternative')alternativeForm(id);
 else if(a==='policy')openDrawer('先核实实际平台规则',`<p class="body">示例没有绑定真实店铺与订单，因此不能确认价保、退货期限或替你申请。请在实际订单页面核对适用条款，再记录处理结果。</p>${btn('返回新发现','close-drawer','primary')}`);
 else if(a==='settings-tab'){ui.settings=value;goto('/settings?tab='+value);}else if(a==='toggle-notification'){state.notifications[key]=!state.notifications[key];persist();refresh();}
 else if(a==='notifications')openDrawer('与你有关的新信息',state.changes.length?state.changes.map(c=>`<div class="list-row"><p>${c.kind==='price'?'同款出现一条新报价':'你添加了更合适的候选'}</p>${link('核对条件','/changes/'+c.id,'btn sm')}</div>`).join(''):`<p class="body">目前没有新变化。这里不会伪造实时通知。</p>${link('管理提醒条件','/settings?tab=notifications','btn')}`);
 else if(a==='logout'){currentUser=null;state=null;sessionStorage.removeItem(KEY+'-user');goto('/');}
 else if(a==='export'){const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const l=document.createElement('a');l.href=u;l.download='My-Best-Choice-decisions.json';l.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 else if(a==='reset')openDrawer('重置当前示例账户？',`<p class="body">将清除这个示例账户在本浏览器的目标、观察和决定。建议先导出。</p><div class="drawer-actions">${btn('确认重置','reset-confirm','danger')}${btn('保留记录','close-drawer','primary')}</div>`);
 else if(a==='reset-confirm'){state=upgradeState(freshState(currentUser));persist();ui.setupStep=0;goto('/setup');}
});
document.addEventListener('submit',ev=>{const form=ev.target;if(!form.id)return;ev.preventDefault();const f=new FormData(form),v=k=>String(f.get(k)||'').trim(),n=k=>v(k)===''?null:Number(v(k)),id=form.dataset.id;const err=s=>{const node=form.querySelector('.field-error');if(node)node.textContent=translateText(s);else toast(s);};
 if(form.id==='setup-form'){if(ui.setupStep===0&&!f.has('consent'))return;if(ui.setupStep===1){state.profile.name=v('name')||state.profile.name;state.profile.priorities=f.getAll('priority');}if(ui.setupStep===2){state.profile.planning=v('planning');finishSetup();}else{ui.setupStep++;persist();render();}return;}
 if(form.id==='product-add-form'){commerceIdentify(form);return;}
 if(form.id==='manual-product-form'){const pid='custom-'+Date.now().toString(36);state.customProducts||={};state.customProducts[pid]={id:pid,name:v('name'),model:v('model'),configuration:v('configuration'),price:n('price'),sourceUrl:v('url'),category:'手动填写',art:'stand',budget:null,purpose:'尚未确认用途',existing:'现有替代方案待填写',emotion:'',social:'',tag:'用户填写 · 证据待补充'};persist();closeDrawer(false);confirmProduct(pid);return;}
 if(form.id==='confirm-product-form'){state.edits[id]={...state.edits[id],variantChanged:v('configuration')==='other',configuration:v('configuration')==='other'?'其他版本 · 配置与保修待确认':(products[id]||state.customProducts[id]).configuration};persist();goto('/products/'+id);return;}
 if(form.id==='product-edit-form'){state.edits[id]={...state.edits[id],purpose:v('purpose'),existing:v('existing'),budget:n('budget'),emotion:v('emotion'),social:v('social'),confirmedAt:new Date().toISOString()};persist();closeDrawer();refresh();toast('已更新本次陈述，原决定快照保持完整。');return;}
 if(form.id==='goal-form'){const g={id:id||'goal-'+Date.now().toString(36),title:v('title'),purpose:v('purpose'),requirements:v('requirements'),months:n('months'),target:n('target'),reserved:n('reserved')||0,monthly:n('monthly')||0,priority:v('priority'),status:'planning',confirmedAt:new Date().toISOString()};const list=state.goals.filter(x=>x.id!==id).concat(g);const check=validatePlan(state,list);if(!check.valid)return err('已分配预留超过可分配总额 '+hk(check.over)+'，请调整。');state.goals=list;state.dismissedProposal=true;persist();goto('/needs/'+g.id);return;}
 if(form.id==='allocation-form'){const check=validatePlan(state,state.goals,n('pool'));if(!check.valid)return err('现有目标已预留 '+hk(check.sum)+'，超过这个总额。请先调整各目标。');state.reservedPool=n('pool');state.experience.funds.pool=n('pool');state.experience.funds.revision++;persist();closeDrawer();refresh();return;}
 if(form.id==='watch-form'){state.watch=state.watch.filter(w=>w.productId!==id);state.watch.push({productId:id,target:n('target'),note:v('note'),enabled:f.has('enabled')});persist();closeDrawer();refresh();toast('观察条件已保存。');return;}
 if(form.id==='decision-form'){if(!v('reason'))return err('请用自己的话写下一条理由。');const d=applyDecision(state,product(state,id),form.dataset.choice,v('reason'),{target:n('target'),note:v('condition')});if(d.choice==='SKIP'&&id==='gpu-5090'&&!f.has('keepGoal'))state.goals.forEach(g=>{if(g.title.includes('显卡'))g.status='archived';});persist();goto('/decisions/'+d.id);toast('决定已保存；购买意向不等于已下单。');return;}
 if(form.id==='purchase-form'){const d=state.decisions.find(x=>x.id===id);d.purchased=true;d.userConfirmed=true;d.paidAmount=n('paidAmount');d.purchasedAt=v('purchasedAt');persist();closeDrawer();refresh();return;}
 if(form.id==='alternative-form'){const c={id:'change-'+Date.now().toString(36),decisionId:id,kind:'alternative',alternativeName:v('name'),alternativePrice:n('price'),alternativeReason:v('reason'),date:new Date().toISOString().slice(0,10)};state.changes.unshift(c);persist();goto('/changes/'+c.id);return;}
 if(form.id==='resolution-form'){const c=state.changes.find(x=>x.id===id);c.resolution=v('resolution');c.resolutionReason=v('reason');persist();toast('已保存你的处理记录，未向商家提交申请。');return;}
 if(form.id==='profile-form'){state.profile.name=v('name')||state.profile.name;state.profile.note=v('profileNote');persist();refresh();toast('资料已保存。');}
});
document.addEventListener('change',ev=>{if(ev.target.dataset.scenarioId){const id=ev.target.dataset.scenarioId;ui.scenario=ev.target.value;openDrawer('换个情境看看',scenarioContent(product(state,id),ui.scenario));$('#scenario')?.focus();}});
document.addEventListener('keydown',ev=>{const d=$('[role="dialog"]');if(!d)return;if(ev.key==='Escape'){closeDrawer();return;}if(ev.key==='Tab'){const focus=[...d.querySelectorAll('button:not(:disabled),a[href],input,select,textarea,[tabindex="0"]')];if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});
window.addEventListener('popstate',()=>{planPreview=null;closeDrawer(false);render();});
render();

function chartTip(ev){const c=ev.target.closest?.("[data-chart-date]");const tip=document.getElementById("chart-tooltip");if(!tip)return;tip.hidden=!c;if(c){tip.textContent=c.dataset.chartDate+" · "+hk(Number(c.dataset.chartPrice))+" · "+translateText("示例记录");tip.style.left="60px";tip.style.top="10px";}}
document.addEventListener("pointerover",chartTip);document.addEventListener("focusin",chartTip);document.addEventListener("keydown",ev=>{if((ev.key==="Enter"||ev.key===" ")&&ev.target.matches?.("circle[data-action]")){ev.preventDefault();ev.target.dispatchEvent(new MouseEvent("click",{bubbles:true}));}});
function imageCard(name,cls='',alt='场景示意'){return `<img class="scene ${cls}" src="/assets/${name}.webp" alt="${alt}" loading="lazy">`;}
function v2Header(title,subtitle,extra=''){return heading(title,subtitle,`<div class="row wrap">${btn('使用说明 ⓘ','v2-help','sm')}${extra}</div>`);}
function needs(){const x=state.experience,order=suggestedOrder(state),changed=order.join()!==x.needs.map(n=>n.id).join();return `${v2Header('我的需求','看看现在需要什么，也为以后做一点准备。',btn(icon('plus','sm')+' 添加需求','v2-add-need','primary sm'))}<section class="panel section"><div class="section-head between"><h2>优先处理</h2><span class="caption">按你确认的顺序安排</span></div>${x.needs.length?x.needs.map((n,i)=>`<article class="need-row"><span class="need-number">${String(i+1).padStart(2,'0')}</span>${imageCard(n.productId==='earbud-aster'?'earbuds':'studio','need-image')}<div class="grow"><h3>${e(n.title)}</h3><p class="caption">${e(n.problem)}</p><div class="row wrap" style="margin-top:9px">${badge(n.amount==null?'金额待确认':'计划 '+hk(n.amount),'outline')}${badge(['影响待核实','仍有替代办法','已经影响任务'][n.severity]||'影响待核实')}</div></div><div class="row wrap">${btn('查看需求 '+icon('arrow','sm'),'v2-need-detail','text-btn',`data-id="${n.id}"`)}${btn(icon('edit','sm'),'v2-edit-need','icon-btn',`data-id="${n.id}" aria-label="修改${e(n.title)}"`)}${btn('↑','v2-move-up','icon-btn',`data-id="${n.id}" ${i===0?'disabled':''} aria-label="将需求向前调整"`)}</div></article>`).join(''):empty('从一个具体问题开始','可以先写遇到的困难，不必选好商品。',btn('添加需求','v2-add-need','primary sm'))}${changed?`<div class="suggestion-banner">${icon('spark','sm')}<span>有新的排序建议，原顺序保持不变。</span>${btn('查看','v2-order','text-btn')}</div>`:''}</section><section class="section"><div class="section-head between"><h2>我关注的领域</h2>${btn('添加关注 '+icon('plus','sm'),'v2-area-add','text-btn')}</div><div class="areas-grid">${x.areas.map(a=>`<button class="area-card" data-action="v2-area-detail" data-id="${a.id}">${imageCard(a.image||'studio')}<span class="area-text"><strong>${e(a.name)}</strong><small><i class="dot"></i> ${e(a.stage)}</small></span>${icon('arrow','sm')}</button>`).join('')}</div><p class="caption" style="margin-top:12px">关注一个领域，不自动建立购买目标或占用预算。</p></section><div class="discovery-link"><div>${icon('spark')}<span>看看智能体为你整理了哪些下一步。</span></div>${link('我的智能体提议 '+icon('arrow','sm'),'/proposals','btn sm')}</div><p class="caption image-note">场景与商品图片为 AI 生成的视觉示意，不代表真实商品实拍。</p>`;}
function proposalCard(id,title,body,image,tags,action){const status=state.experience.proposalStatus[id];return `<article class="proposal-hero ${status?'handled':''}">${imageCard(image,'proposal-photo')}<div class="proposal-copy"><div class="row wrap">${badge(id==='order'?'计划调整':id==='purchase'?'购买分析':'新方向','green')}${badge(status==='deferred'?'暂不考虑':status==='added'?'已加入需求':status==='followed'?'已加入关注':'待你确认','outline')}</div><h2>${title}</h2><p>${body}</p><div class="basis-tags"><span>推荐依据</span>${tags.map(t=>badge(e(t))).join('')}</div><p class="caption">固定示例，用于说明操作；个性化分析请查看上方 Poe 结果。</p><div class="row wrap" style="margin-top:22px">${btn(action,id==='order'?'v2-order':id==='purchase'?'v2-check-purchase':'v2-run-task','primary sm',`data-id="${id}"`)}${!status?btn(id==='storage'?'加入关注':'加入我的需求','v2-proposal-add','sm',`data-id="${id}"`):btn('重新查看','v2-proposal-restore','sm',`data-id="${id}"`)}${btn('暂不考虑','v2-proposal-defer','text-btn',`data-id="${id}"`)}</div></div></article>`;}
function proposals(){const filter=ui.proposalFilter||'all',vs=proposalViews(state);return `${v2Header('我的智能体提议','从你的任务与兴趣出发，提供值得考虑的下一步。',btn('修改推荐依据','v2-basis','sm'))}${aiPanel('direction')}<div class="between wrap section"><div class="tabs">${[['all','全部'],['direction','新方向'],['purchase','购买分析'],['order','计划调整']].map(([k,v])=>`<button class="tab ${filter===k?'active':''}" data-action="v2-proposal-filter" data-value="${k}">${v}</button>`).join('')}</div>${badge('本期整理 · 示例','amber')}</div>${filter==='all'||filter==='direction'?`${proposalCard('gpu','先验证现有设备，再决定是否升级','示例情境：希望半年内尝试本地 AI 创作，现有设备的限制还未核实。','studio',['创作任务','现有设备','未来安排'],'开始检查')}<section class="section"><div class="section-head between"><h2>四个我，分别怎么看</h2>${btn('查看本次依据 '+icon('arrow','sm'),'v2-basis','text-btn')}</div><div class="agent-grid">${vs.map((v,i)=>`<article class="agent-card ${v.color}"><div class="between"><span class="caption">0${i+1}</span><button class="info-dot" data-action="v2-agent-help" data-key="${v.key}" aria-label="了解${v.name}">ⓘ</button></div><div class="agent-title">${icon(v.icon,'lg')}<h3>${v.name}</h3></div><span class="agent-en">${v.en}</span><p class="agent-quote">${e(v.quote)}</p><div class="agent-source"><p>依据：${e(v.source)}</p><p>待核实：${e(v.unknown)}</p></div><div class="agent-actions">${btn('查看依据','v2-agent-evidence','sm',`data-key="${v.key}"`)}${btn('不符合我的想法','v2-agent-correct','text-btn',`data-key="${v.key}"`)}</div></article>`).join('')}</div></section>${proposalCard('storage','素材存储与备份','因为示例任务提到素材管理困难，可以先检查现有备份方式。','storage',['任务困难','现有物品'],'先了解')}`:''}${filter==='purchase'?proposalCard('purchase','价格合适，还要确认新耳机解决了什么','耳机在示例计划内；连接表现、保修和实际用途仍值得核对。','earbuds',['当前报价','用户用途','购买计划'],'查看购买分析'):''}${filter==='order'?`${proposalCard('order','先处理更影响当前任务的需求','根据你确认的实际困难提出顺序建议。原顺序不变，接受后才更新。','studio',['实际困难','可用替代办法'],'比较建议顺序')}`:''}<p class="caption image-note">下方固定提议为可交互示例；上方 Poe 分析需主动生成，无后台定期推送；未来可按月整理少量方向，频率由你设置。</p>`;}
function donut(summary){if(summary.pool==null||summary.pool<=0)return `<div class="donut-empty">${icon('wallet','lg')}<h3>先确认可分配金额</h3><p class="caption">没有填写时，不推断你的资金状况。</p></div>`;const colors=['#167A68','#276276','#89ADA0','#A56D48','#685F86'];const segments=summary.segments.filter(s=>s.value>0);if(summary.unallocated>0)segments.push({key:'free',label:'未分配',value:summary.unallocated,color:'#D3D8D5'});let offset=0;return `<div class="donut-wrap"><svg viewBox="0 0 280 280" class="donut" role="group" aria-label="资金安排环形图"><circle cx="140" cy="140" r="105" fill="none" stroke="#E8ECE6" stroke-width="43"/>${segments.map((s,i)=>{const pct=s.value/summary.pool*100;const out=`<circle cx="140" cy="140" r="105" fill="none" stroke="${s.color||colors[i%colors.length]}" stroke-width="43" pathLength="100" stroke-dasharray="${pct} ${100-pct}" stroke-dashoffset="${-offset}" style="--arc:${pct} ${100-pct}" transform="rotate(-90 140 140)" tabindex="0" role="button" aria-label="${e(s.label)} ${hk(s.value)}" data-action="v2-segment" data-segment="${e(s.key)}" data-label="${e(s.label)}" data-amount="${s.value}"/>`;offset+=pct;return out;}).join('')}</svg><div class="donut-center"><strong data-count="fund-pool" data-number="${summary.pool}">${hk(summary.pool)}</strong><span>可分配总额</span></div><div id="donut-tooltip" class="donut-tooltip" hidden></div></div><div class="fund-legend">${segments.map(s=>`<button class="legend-row" data-action="v2-segment" data-segment="${e(s.key)}" data-label="${e(s.label)}" data-amount="${s.value}"><span class="legend-dot" style="background:${s.color}"></span><span class="grow">${e(s.label)}</span><strong data-count="segment-${e(s.key)}" data-number="${s.value}">${hk(s.value)}</strong><small>${Math.round(s.value/summary.pool*100)}%</small></button>`).join('')}</div>`;}
function fundingChart(g,previewGoal){if(!g)return empty('还没有长期目标','确认一个未来方向后，可以在这里安排准备。',link('查看我的需求','/needs','btn sm'));if(g.target==null||g.target<=0)return `<p class="body">先确认目标金额，再显示准备进度。</p>${btn('补充目标金额','edit-goal','sm',`data-id="${g.id}"`)}`;const range=ui.fundRange||12,max=Math.max(g.target,g.reserved,1)*1.15,W=650,H=250,x=t=>46+t/range*580,y=v=>207-v/max*180;const points=Array.from({length:range+1},(_,i)=>({month:i,value:Math.min(g.target,Number(g.reserved||0)+Number(g.monthly||0)*i)}));const d=points.map((p,i)=>`${i?'L':'M'}${x(i)},${y(p.value)}`).join(' '),targetY=y(g.target);return `<div class="fund-chart-wrap"><div class="chart-tooltip fund-tooltip" id="fund-tooltip" hidden></div><svg viewBox="0 0 ${W} ${H}" class="fund-chart" role="group" aria-label="实际预留与未来计划折线图">${[0,.25,.5,.75,1].map(i=>{const val=g.target*i;return `<line x1="46" x2="626" y1="${y(val)}" y2="${y(val)}" stroke="#E1E5E0" stroke-dasharray="3 4"/><text x="37" y="${y(val)+4}" text-anchor="end">${fmt(val)}</text>`;}).join('')}<line x1="46" x2="626" y1="${targetY}" y2="${targetY}" stroke="#A56D48" stroke-dasharray="3 5"/><text x="625" y="${targetY-8}" text-anchor="end">目标 ${fmt(g.target)}</text><path class="draw-line" d="${d}" fill="none" stroke="#167A68" stroke-width="2.6" stroke-dasharray="6 6"/>${previewGoal?`<path d="${points.map((p,i)=>`${i?'L':'M'}${x(i)},${y(Math.min(g.target,previewGoal.reserved+Number(g.monthly||0)*i))}`).join(' ')}" fill="none" stroke="#A56D48" stroke-width="2" stroke-dasharray="3 5"/>`:''}<circle cx="46" cy="${y(g.reserved)}" r="6" fill="#167A68" stroke="#FBFAF7" stroke-width="3"/>${points.map(p=>`<circle cx="${x(p.month)}" cy="${y(p.value)}" r="9" fill="transparent" role="button" tabindex="0" aria-label="${p.month?'未来'+p.month+'个月计划':'当前已确认'} ${hk(p.value)}" data-action="v2-fund-point" data-month="${p.month}" data-amount="${p.value}"/>`).join('')}<text x="46" y="239">现在</text><text x="626" y="239" text-anchor="end">${range} 个月后</text></svg></div><div class="between wrap caption"><span><i class="line-key"></i> 当前实际记录：${hk(g.reserved)}</span><span><i class="line-key dashed"></i> 未来计划 · 非预测收益</span></div><p class="caption" style="margin-top:10px">当前只有一条实际预留记录。未来投入不计入当前资金；目标金额不是市场报价。</p>`;}
function plans(){const sum=fundSummary(state),active=state.goals.filter(g=>g.status!=='archived'),g=active.find(g=>g.id===ui.fundGoal)||active[0],pg=planPreview?.ok&&planPreview.delay?.goalId===g?.id?planPreview.next.goals.find(v=>v.id===g.id):null;return `${v2Header('我的计划','每一笔安排，都看得见取舍。',btn('分析已有计划','ai-plan-select','sm')+' '+btn(icon('plus','sm')+' 添加目标','new-goal','primary sm'))}<div class="plan-grid section"><section class="panel funds-panel"><div class="section-head between"><h2>资金安排</h2>${btn(icon('edit','sm'),'allocation','icon-btn','aria-label="修改可分配总额"')}</div><p class="caption">用户确认的可分配金额 · 非银行余额</p>${donut(sum)}${!sum.valid?`<p class="field-error">预留已超过总额，请先调整目标或总额。</p>`:''}${sum.pool==null?`<div class="stack" style="margin-top:20px">${btn('确认我的金额','allocation','primary sm')}${btn('载入资金安排示例','v2-load-plan','sm')}</div><p class="caption" style="margin-top:12px">示例将明确载入：显卡预留 HK$6,000、耳机预留 HK$600 与未分配 HK$3,400。</p>`:''}</section><section class="panel readiness-panel"><div class="readiness-head">${imageCard('studio')}<div><span class="eyebrow">PREPARE WITH INTENTION</span><h2>${g?'目标准备':'为未来留一点准备'}</h2>${g?`<select class="goal-select" aria-label="选择准备目标" id="fund-goal">${active.map(x=>`<option value="${x.id}" ${g.id===x.id?'selected':''}>${e(x.title)}</option>`).join('')}</select>`:''}</div></div>${g?`<div class="plan-metrics"><div><small>计划目标</small><strong>${hk(g.target)}</strong></div><div><small>已预留</small><strong>${hk(g.reserved)}</strong></div><div><small>每月计划准备</small><strong>${hk(g.monthly)}</strong></div></div><div class="between wrap" style="margin-bottom:14px"><div class="tabs">${[6,12,24].map(n=>`<button class="tab ${Number(ui.fundRange||12)===n?'active':''}" data-action="v2-fund-range" data-value="${n}">${n}个月</button>`).join('')}</div>${btn('调整计划','edit-goal','text-btn',`data-id="${g.id}"`)}</div>`:''}${fundingChart(g,pg)}</section></div><section class="impact-panel section" id="purchase-impact"><div class="section-head between"><h2>购买影响预览</h2>${badge(planPreview?'预览中 · 尚未保存':'先预览，再确认','amber')}</div>${impactContent()}</section>${state.experience.funds.committed.length?`<section class="panel section"><h3>已经安排的购买</h3><p class="caption" style="margin:7px 0 15px">这是资金安排，不代表已下单或实际扣款。</p>${state.experience.funds.committed.map(a=>`<div class="list-row"><div class="grow"><h4>${e(product(state,a.productId)?.name||a.productId)}</h4><p>${hk(a.amount)} · 用户确认的安排</p></div>${btn('取消此安排','v2-cancel-allocation','sm',`data-id="${a.id}"`)}</div>`).join('')}</section>`:''}<section class="section"><div class="section-head between"><h2>长期目标</h2>${link('查看我的需求','/needs','text-btn')}</div>${active.length?`<div class="grid-2">${active.map(goalCard).join('')}</div>`:empty('目标可以从一个具体需要开始','先确认用途、现有办法和需要时间。',link('前往我的需求','/needs','btn sm'))}</section><p class="caption image-note">当前为示例业务资料；图片为 AI 生成的视觉示意。</p>`;}
function impactContent(){const pid=ui.impactProduct||'earbud-aster',p=product(state,pid)||product(state,'earbud-aster'),price=priceFor(state,p),f=state.experience.funds,own=f.earmarks[p.id]||0,source=ui.impactSource||(own?'earmark':'unallocated'),pr=planPreview;return `<div class="impact-grid">${imageCard(p.art==='gpu'?'studio':'earbuds','impact-image')}<form id="v2-impact-form"><h3>${e(p.name)}</h3><p class="caption" style="margin-top:5px">当前示例到手价 <strong>${hk(price)}</strong></p><div class="field" style="margin-top:15px"><label for="impact-product">选择商品</label><select name="productId" id="impact-product">${Object.values({...products,...state.customProducts}).map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${e(x.name)}</option>`).join('')}</select></div><div class="field"><label for="impact-source">资金来源</label><select id="impact-source" name="source">${own?`<option value="earmark" ${source==='earmark'?'selected':''}>商品专属预留 · ${hk(own)}</option>`:''}<option value="unallocated" ${source==='unallocated'?'selected':''}>未分配金额 · ${hk(fundSummary(state).unallocated)}</option>${state.goals.filter(g=>g.status!=='archived').map(g=>`<option value="goal:${g.id}" ${source==='goal:'+g.id?'selected':''}>${e(g.title)} · ${hk(g.reserved)}</option>`).join('')}</select></div>${own&&source!=='earmark'?`<label class="check-row"><input type="checkbox" name="release" ${ui.releaseEarmark?'checked':''}>释放原专属预留 ${hk(own)}，改用所选来源，避免重复安排</label>`:own?`<p class="caption">优先使用商品专属预留，剩余金额继续保留。</p>`:''}<button class="btn primary sm" type="submit" style="margin-top:15px">预览影响 ${icon('arrow','sm')}</button></form><div class="impact-result" aria-live="polite">${!pr?`<h3>先看看，再安排。</h3><p>预览不会改变资金，也不会替你下单。</p><p class="caption">${own?'已识别商品专属预留，避免重复占用未分配金额。':'选择来源后，再看对其他目标的影响。'}</p>`:!pr.ok?`<div class="note-banner warn">${icon('info')}<span>${e(pr.error)}</span></div>`:`<div class="impact-numbers"><div><small>调整前未分配</small><strong>${hk(pr.before.unallocated)}</strong></div>${icon('arrow')}<div><small>调整后未分配</small><strong>${hk(pr.after.unallocated)}</strong></div></div><p class="impact-status">${icon(pr.delay?'info':'check','sm')}${pr.delay?`${e(pr.delay.title)}：预留 ${hk(pr.delay.beforeReserved)} → ${hk(pr.delay.afterReserved)}`:'其他长期目标的预留不受影响'}</p>${pr.delay?`<p class="caption">按当前每月投入，准备时间 ${pr.delay.beforeMonths??'待确认'} → ${pr.delay.afterMonths??'待确认'} 个月。${pr.delay.months==null?'每月投入不足，无法确定。':`约增加 ${pr.delay.months} 个月。`}</p>`:''}${pr.earmarkBefore?`<p class="caption">耳机专属预留 ${hk(pr.earmarkBefore)} → ${hk(pr.earmarkAfter)}${pr.source!=='earmark'?'，释放金额已退回未分配。':''}</p>`:''}<p class="caption">将安排 ${hk(pr.amount)}；此处不是支付操作。</p><div class="row wrap" style="margin-top:16px">${btn('确认调整','v2-impact-confirm','primary sm')}${btn('取消预览','v2-impact-cancel','sm')}</div>`}</div></div>`;}
function helpDrawer(key){const roles={use:['正在使用的我','实际使用价值','任务、现有物品、可用替代办法与性能证据','帮助确认商品能否解决当前的问题'],price:['精打细算的我','成本与安排','完整到手价、时间、预留及其他目标','帮助理解这次选择会占用什么'],emotion:['感受当下的我','情感与体验价值','你主动表达的喜欢、快乐和体验期待','帮助分辨你真正期待的体验'],social:['在意形象的我','社会影响与身份表达','你确认的推荐、群体认同和身份表达','帮助理解他人的眼光如何参与选择']};if(key){const r=roles[key];openDrawer(r[0]+'是什么？',`<p class="body">我代表你对<strong>${r[1]}</strong>的考虑。</p><div class="source-card"><h3>我参考什么</h3><p>${r[2]}</p></div><div class="source-card"><h3>我提供什么</h3><p>${r[3]}</p></div><p class="hint">资料不足时明确说未知；我的表达不是你已经认可的想法。你可以查看依据、修改资料或纠正我。</p>${btn('明白了','close-drawer','primary sm')}`);return;}
 openDrawer('使用说明',`<div class="help-steps"><section><span class="eyebrow">01 / HOW IT WORKS</span><h3>从关注到决定</h3><p>关注方向 → 确认需求 → 检查候选 → 安排资金 → 保存 BUY、WAIT 或 SKIP。</p><p>排序以实际困难为先。系统只提议，用户确认后才改变正式顺序。</p></section><section><span class="eyebrow">02 / YOUR INFORMATION</span><h3>提议从哪里来</h3><p>参考你确认的职业、兴趣、任务、现有条件与未来安排。没有填写的资料不自行推断。</p>${btn('修改推荐依据','v2-basis','text-btn')}</section><section><span class="eyebrow">03 / FOUR PERSPECTIVES</span><h3>四个我是什么</h3><p>同一个人的四种价值视角，用第一人称说明理由、依据与未知事项，不是固定人格或投票。</p>${Object.entries(roles).map(([k,r])=>btn(r[0]+' ⓘ','v2-agent-help','sm',`data-key="${k}"`)).join(' ')}</section><section><span class="eyebrow">04 / PLAN BEFORE CONFIRMING</span><h3>资金图怎么看</h3><p>环形图包含各目标预留、商品专属预留、已安排购买和未分配金额。未来计划不计入当前资金。先预览影响，确认后才保存；不代替支付。</p></section><section><span class="eyebrow">05 / CURRENT SCOPE</span><h3>当前资料与未来概念</h3><p>当前价格、评价与固定方向提议为示例。可在 Poe 区域连接密钥、预览资料后主动生成分析；没有市场抓取或定期后台服务。未来可按月整理少量方向，频率可设置。</p><p>浏览器历史、社交媒体、聊天记录与长期人格推断保留为未来概念，当前没有实际采集。</p>${link('查看未来数据接入概念','/settings?tab=connected','text-btn')}</section></div>`);}
function basisForm(){const b=state.experience.basis,x=state.experience;openDrawer('本次依据与我的想法',`<p class="body">先记录实际情况，再表达自己的想法。四个我会引用这些资料；留空代表未知，不替你补成人格判断。</p><form id="v2-basis-form"><h3>实际情况</h3><p class="caption">建议先写清当前问题、现有办法与金额范围。</p>${textarea('tasks','我现在想解决什么问题',b.tasks||'','例如：通勤耳机经常断连，希望改善连接稳定性。')}${textarea('equipment','我已经有什么，可以怎样替代',b.equipment||'','例如：已有一副可使用的耳机，只是连接不稳定。')}${field('budget','我愿意投入的金额范围',b.budget||'','text','例如：HK$600 以内，不占用旅行预留。')}${field('time','什么时候需要／可以投入多少时间',b.time||'','text','例如：一个月内，不急着今天下单。')}<h3>我的想法</h3>${textarea('priority','这次最重要的取舍',b.priority||'','例如：连接稳定比外观重要，不为了特价买重复设备。')}${textarea('emotion','我期待怎样的体验（可选）',x.emotion||'','例如：想让通勤更安静；没有特别期待也可以直说。')}${textarea('social','别人的推荐或形象是否影响我（可选）',x.social||'','例如：朋友推荐让我关注它，但品牌形象不重要；也可以填写“没有影响”。')}<details class="source-card"><summary>补充背景与未来安排（可选）</summary>${[['occupation','职业或常做的事'],['interests','关注的兴趣领域'],['skills','已经会的技能'],['future','半年到一年的安排']].map(([k,l])=>field(k,l,b[k]||'')).join('')}</details><div class="field"><label for="digestFrequency">方向整理频率（未来服务设置）</label><select id="digestFrequency" name="digestFrequency">${['每月一次','每季度一次','仅手动查看'].map(v=>`<option ${x.digestFrequency===v?'selected':''}>${v}</option>`).join('')}</select><span class="caption">当前只保存偏好，不会实际定时发送。</span></div><p class="hint">输入框里的耳机例子只是填写提示，不会自动保存成你的资料。保存仅更新依据，不自动发送给 AI。</p><button class="btn primary" type="submit">确认我的依据与想法</button></form>`);}

function needForm(id){const n=state.experience.needs.find(x=>x.id===id)||{};openDrawer(id?'修改这项需求':'添加一个需求',`<form id="v2-need-form" data-id="${id||''}">${field('title','想解决什么',n.title||'','text','','required')}${textarea('problem','现在遇到的困难',n.problem||'')}${textarea('alternative','现有办法或替代方案',n.alternative||'')}${field('area','所属关注领域（可选）',n.area||ui.relatedArea||'')}<div class="field"><label for="severity">目前影响</label><select id="severity" name="severity">${[[0,'影响还不确定'],[1,'有不便，但仍有办法'],[2,'已经无法完成明确任务']].map(([k,l])=>`<option value="${k}" ${n.severity===k?'selected':''}>${l}</option>`).join('')}</select></div>${field('months','预计几个月内需要',n.months??'','number','','min="1" max="120"')}${field('amount','本次计划金额 HK$',n.amount??'','number','留空表示待确认','min="0"')}<div class="field"><label for="productId">关联候选（可不选）</label><select id="productId" name="productId"><option value="">还没有候选</option>${Object.values({...products,...state.customProducts}).map(p=>`<option value="${p.id}" ${n.productId===p.id?'selected':''}>${e(p.name)}</option>`).join('')}</select></div><button class="btn primary" type="submit">确认需求</button></form>`);}
function needDetail(id){const n=state.experience.needs.find(n=>n.id===id);if(!n)return;openDrawer(n.title,`${imageCard(n.productId==='earbud-aster'?'earbuds':'studio','drawer-scene')}<div class="source-card"><h3>目前的困难</h3><p>${e(n.problem||'尚未填写')}</p><p class="caption">实际影响：${['待核实','有不便，仍有办法','已影响明确任务'][n.severity]}</p></div><div class="source-card"><h3>现有办法</h3><p>${e(n.alternative||'待核实')}</p></div><p class="body">计划：${hk(n.amount)} · 预计 ${n.months||'待确认'} 个月内。需求本身不自动占用资金。</p><div class="row wrap">${n.productId?link('检查候选商品','/products/'+n.productId,'btn primary sm'):link('添加候选商品','/products/new','btn primary sm')}${btn('编辑需求','v2-edit-need','sm',`data-id="${id}"`)}${btn('建立准备目标','v2-need-goal','sm',`data-id="${id}"`)}</div>`);}
function orderDrawer(){const x=state.experience,ids=suggestedOrder(state),different=ids.join()!==x.needs.map(n=>n.id).join();openDrawer('查看排序建议',`<p class="body">首先比较哪项需求更影响当前任务，再看现有替代办法。相同影响程度保持原顺序。</p><div class="grid-2"><div class="source-card"><h3>你目前的顺序</h3>${x.needs.map((n,i)=>`<p>${i+1}. ${e(n.title)}</p>`).join('')}</div><div class="source-card"><h3>建议顺序</h3>${ids.map((id,i)=>{const n=x.needs.find(n=>n.id===id);return `<p>${i+1}. ${e(n.title)}<br><span class="caption">${e(n.problem)}</span></p>`;}).join('')}</div></div><p class="hint">${different?'确认后只改变顺序，不自动挪用任何资金。':'目前无需调整。你仍可在需求卡片上自行调整。'}</p><div class="drawer-actions">${different?btn('接受建议顺序','v2-order-confirm','primary sm'):''}${btn('保留原顺序','close-drawer','sm')}</div>${x.orderLog.length?`<details class="source-card"><summary>查看调整记录（${x.orderLog.length}）</summary>${x.orderLog.slice(-5).reverse().map(l=>`<p class="caption">${new Date(l.date).toLocaleString('zh-CN')} · ${e(l.reason)}</p>`).join('')}</details>`:''}`);}
function addArea(){openDrawer('添加关注领域',`<p class="body">关注不会自动建立需求或占用资金。</p><form id="v2-area-form">${field('name','领域名称','','text','','required')}<button class="btn primary" type="submit">加入关注</button></form>`);}
function taskForm(){openDrawer('检查现有设备能否完成任务',`<p class="body">先用一个实际任务验证。这里由你手动记录，没有自动扫描设备。</p><form id="v2-task-form">${textarea('task','这次尝试完成什么',state.experience.basis.tasks||'')}<div class="field"><label for="readiness">运行结果</label><select name="readiness" id="readiness"><option value="unknown">还没有验证</option><option value="works">现有设备可以完成</option><option value="blocked">无法完成，存在具体限制</option></select></div>${textarea('limitation','实际遇到了什么限制',state.experience.limitation||'')}<p class="caption">记录后会更新相关视角和排序建议，正式顺序保持不变。</p><button class="btn primary" type="submit">保存我的检查结果</button></form>`);}
function segmentDrawer(key){const s=fundSummary(state);if(key==='free'){openDrawer('未分配金额',`<p class="body">当前可分配总额中尚未安排的部分：${hk(s.unallocated)}。</p><p class="hint">只依据用户确认的总额计算，不代表银行余额。</p>${btn('修改可分配总额','allocation','sm')}`);}else if(key==='committed'){scrollToBlock('purchase-impact');toast('已安排购买在下方列出，可以单独取消。');}else if(key.startsWith('goal:'))goalForm(key.slice(5));else{openDrawer('商品专属预留',`<p class="body">${e(product(state,key.slice(8))?.name||key.slice(8))} 的专属预留：${hk(state.experience.funds.earmarks[key.slice(8)])}</p><p class="hint">预览购买时优先使用这笔预留，剩余继续保留；改用其他来源必须先确认释放。</p>${btn('去预览购买影响','v2-go-impact','primary sm')}`);}}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action^="v2-"]');if(!el||el.disabled)return;ev.preventDefault();const {action:a,id,key,value}=el.dataset;
 if(a==='v2-help')helpDrawer();else if(a==='v2-agent-help')helpDrawer(key);else if(a==='v2-basis')basisForm();else if(a==='v2-add-need'){ui.relatedArea=el.dataset.area||'';needForm();}else if(a==='v2-edit-need')needForm(id);else if(a==='v2-need-detail')needDetail(id);else if(a==='v2-area-add')addArea();
 else if(a==='v2-need-goal'){const n=state.experience.needs.find(n=>n.id===id);goalForm(null);$('#title').value=n.title;$('#purpose').value=n.problem;if(n.amount!=null)$('#target').value=n.amount;}
 else if(a==='v2-move-up'){const list=state.experience.needs.map(n=>n.id),i=list.indexOf(id);if(i<1)return;[list[i-1],list[i]]=[list[i],list[i-1]];openDrawer('确认调整顺序',`<p class="body">将“${e(state.experience.needs[i].title)}”向前调整一位？</p><p class="hint">不影响任何资金预留。</p><div class="drawer-actions">${btn('确认调整','v2-order-manual','primary sm',`data-id="${id}"`)}${btn('取消','close-drawer','sm')}</div>`);}
 else if(a==='v2-order-manual'){const ids=state.experience.needs.map(n=>n.id),i=ids.indexOf(id);if(i>0){[ids[i-1],ids[i]]=[ids[i],ids[i-1]];acceptOrder(state,ids,'用户手动调整');persist();closeDrawer();refresh();}}
 else if(a==='v2-order')orderDrawer();else if(a==='v2-order-confirm'){acceptOrder(state,suggestedOrder(state));persist();closeDrawer();refresh();toast('顺序已调整，资金安排保持不变。');}
 else if(a==='v2-area-detail'){const area=state.experience.areas.find(x=>x.id===id),ns=state.experience.needs.filter(n=>n.area===area.name);openDrawer(area.name,`${imageCard(area.image||'studio','drawer-scene')}<p class="body">阶段：${e(area.stage)}。关注这个方向，不意味着需要购买。</p>${ns.length?ns.map(n=>`<div class="source-card"><h3>${e(n.title)}</h3><p>${e(n.problem)}</p>${btn('查看需求','v2-need-detail','sm',`data-id="${n.id}"`)}</div>`).join(''):'<p class="hint">还没有确认的具体需求，可以先了解或记录现有条件。</p>'}<div class="row wrap">${btn('添加相关需求','v2-add-need','primary sm',`data-area="${e(area.name)}"`)}${btn('取消关注','v2-area-remove','sm',`data-id="${id}"`)}</div>`);}
 else if(a==='v2-area-remove'){state.experience.areas=state.experience.areas.filter(x=>x.id!==id);persist();closeDrawer();refresh();}
 else if(a==='v2-proposal-filter'){ui.proposalFilter=value;refresh();}else if(a==='v2-proposal-defer'){state.experience.proposalStatus[id]='deferred';persist();refresh();toast('本条提议已暂缓，不影响已确认的需求。');}else if(a==='v2-proposal-restore'){delete state.experience.proposalStatus[id];persist();refresh();}
 else if(a==='v2-proposal-add'){if(id==='storage'){if(!state.experience.areas.some(a=>a.name==='素材存储与备份'))state.experience.areas.push({id:'storage',name:'素材存储与备份',stage:'正在了解',image:'storage'});state.experience.proposalStatus[id]='followed';persist();refresh();toast('已加入关注，不占用预算。');}else{const existing=state.experience.needs.find(n=>n.productId===(id==='gpu'?'gpu-5090':'earbud-aster'));if(existing){state.experience.proposalStatus[id]='added';persist();refresh();toast('已关联现有需求，不重复创建。');needDetail(existing.id);}else{needForm();$('#title').value=id==='gpu'?'验证本地创作设备需求':'改善通勤耳机连接';$('#productId').value=id==='gpu'?'gpu-5090':'earbud-aster';}}}
 else if(a==='v2-run-task'){if(id==='storage')openDrawer('先检查现有备份',`<p class="body">列出现有素材、可用容量和备份位置；确认哪些文件只有一份，再考虑是否需要新设备。</p>${btn('补充我的设备与任务','v2-basis','primary sm')}`);else taskForm();}
 else if(a==='v2-check-purchase')goto('/products/earbud-aster');else if(a==='v2-agent-evidence'){const v=proposalViews(state).find(v=>v.key===key);openDrawer(v.name+' · 本次依据',`<p class="body">${e(v.source)}</p><div class="source-card"><h3>尚未确认</h3><p>${e(v.unknown)}</p></div>${btn('修改这些资料','v2-agent-correct','primary sm',`data-key="${key}"`)}`);}
 else if(a==='v2-agent-correct'){if(key==='use'||key==='price')basisForm();else openDrawer('纠正我的理解',`<form id="v2-view-form" data-key="${key}">${textarea('statement',key==='emotion'?'我期待的体验':'推荐、群体或身份对这次选择的影响',state.experience[key]||'')}<p class="caption">留空则恢复为未知，不会推断你的长期性格。</p><button class="btn primary" type="submit">确认我的表达</button></form>`);}
 else if(a==='v2-load-plan'){loadPlanExample(state);persist();refresh();toast('已明确载入资金安排示例。');}
 else if(a==='v2-fund-range'){ui.fundRange=Number(value);refresh();}else if(a==='v2-segment')segmentDrawer(el.dataset.segment);else if(a==='v2-go-impact'){closeDrawer();scrollToBlock('purchase-impact');}
 else if(a==='v2-impact-confirm'){try{commitPurchasePreview(state,planPreview);planPreview=null;persist();refresh();toast('资金安排已保存，尚未下单。');}catch(error){planPreview=null;refresh();toast(error.message);}}
 else if(a==='v2-impact-cancel'){planPreview=null;refresh();toast('已取消预览，正式计划未改变。');}
 else if(a==='v2-cancel-allocation'){openDrawer('取消这笔资金安排？',`<p class="body">将按原来源退回预留；这不会取消任何真实订单。</p><div class="drawer-actions">${btn('确认取消安排','v2-cancel-allocation-confirm','primary sm',`data-id="${id}"`)}${btn('保留','close-drawer','sm')}</div>`);}
 else if(a==='v2-cancel-allocation-confirm'){try{cancelAllocation(state,id);persist();planPreview=null;closeDrawer();refresh();}catch(error){toast(error.message);}}
 else if(a==='v2-fund-point'){openDrawer('准备记录与计划',`<p class="body">${Number(el.dataset.month)?'未来 '+el.dataset.month+' 个月的计划金额':'当前用户确认的预留'}：${hk(Number(el.dataset.amount))}。</p><p class="hint">未来计划取决于你填写的投入，不是当前现金或市场预测。</p>`);}
});
document.addEventListener('submit',ev=>{const form=ev.target;if(!form.id.startsWith('v2-'))return;ev.preventDefault();const f=new FormData(form),v=k=>String(f.get(k)||'').trim(),n=k=>v(k)===''?null:Number(v(k)),id=form.dataset.id;
 if(form.id==='v2-basis-form'){for(const k of Object.keys(state.experience.basis))state.experience.basis[k]=v(k);state.experience.basis.priority=v('priority');state.experience.emotion=v('emotion');state.experience.social=v('social');state.experience.basisConfirmed=true;state.experience.digestFrequency=v('digestFrequency');persist();closeDrawer();refresh();toast('已保存你确认的推荐依据。');}
 else if(form.id==='v2-need-form'){const old=state.experience.needs.find(n=>n.id===id),p=product(state,v('productId'));const data={...old,confirmedAt:new Date().toISOString(),id:id||'need-'+Date.now().toString(36),title:v('title'),problem:v('problem'),alternative:v('alternative'),severity:n('severity')||0,months:n('months'),amount:n('amount'),productId:v('productId'),area:v('area')||(p?.art==='gpu'?'本地 AI 创作':p?.art==='earbuds'?'通勤音频':'')};if(old)Object.assign(old,data);else state.experience.needs.push(data);if(p)state.edits[p.id]={...state.edits[p.id],purpose:data.problem,existing:data.alternative,budget:data.amount};persist();closeDrawer();goto('/needs');toast('已保存需求；排序建议需要你另行确认。');}
 else if(form.id==='v2-area-form'){if(!state.experience.areas.some(a=>a.name===v('name')))state.experience.areas.push({id:'area-'+Date.now().toString(36),name:v('name'),stage:'正在了解',image:'studio'});persist();closeDrawer();refresh();}
 else if(form.id==='v2-view-form'){state.experience[form.dataset.key]=v('statement');persist();closeDrawer();refresh();}
 else if(form.id==='v2-task-form'){state.experience.readiness=v('readiness');state.experience.limitation=v('limitation');if(v('task')){state.experience.basis.tasks=v('task');state.experience.basisConfirmed=true;}const need=state.experience.needs.find(n=>n.productId==='gpu-5090');if(need){need.severity=v('readiness')==='blocked'?2:0;need.problem=v('readiness')==='blocked'?(v('limitation')||'用户确认现有设备无法完成任务'):v('readiness')==='works'?'现有设备能够完成当前任务':'实际限制尚未验证';}persist();closeDrawer();refresh();toast('检查结果已保存；原需求顺序保持不变。');}
 else if(form.id==='v2-impact-form'){ui.impactProduct=v('productId');ui.impactSource=v('source');ui.releaseEarmark=f.has('release');planPreview=previewPurchase(state,{productId:ui.impactProduct,price:priceFor(state,product(state,ui.impactProduct)),source:ui.impactSource,releaseEarmark:ui.releaseEarmark});refresh();requestAnimationFrame(()=>scrollToBlock('purchase-impact'));}
});
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='fund-goal'){ui.fundGoal=t.value;refresh();}else if(t.id==='impact-product'){ui.impactProduct=t.value;ui.impactSource=null;planPreview=null;refresh();}else if(t.id==='impact-source'){ui.impactSource=t.value;ui.releaseEarmark=false;planPreview=null;refresh();}});
function fundHover(ev){const t=ev.target.closest?.('[data-segment],[data-month]');const donut=$('#donut-tooltip'),fund=$('#fund-tooltip');if(donut)donut.hidden=!t?.dataset.segment;if(fund)fund.hidden=t?.dataset.month==null;if(t?.dataset.segment&&donut){donut.textContent=displayPlain(t.dataset.label)+' · '+hk(Number(t.dataset.amount));}if(t?.dataset.month!=null&&fund){fund.textContent=translateText(Number(t.dataset.month)?'未来'+t.dataset.month+'个月计划':'当前已确认')+' · '+hk(Number(t.dataset.amount));}}
document.addEventListener('pointerover',fundHover);document.addEventListener('focusin',fundHover);document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches?.('circle[data-segment],circle[data-month]')){ev.preventDefault();ev.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});

function animatePlanNumbers(){if(!document.querySelectorAll)return;const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;for(const el of document.querySelectorAll('[data-count]')){const k=el.dataset.count,target=Number(el.dataset.number),before=numberMemory.get(k);numberMemory.set(k,target);if(reduce||before==null||before===target)continue;let start;function tick(t){start??=t;const progress=Math.min(1,(t-start)/350),value=before+(target-before)*(1-Math.pow(1-progress,3));el.textContent=hk(Math.round(value));if(progress<1&&el.isConnected)requestAnimationFrame(tick);}requestAnimationFrame(tick);}}

// Poe credentials and results intentionally live only in this tab's memory.
function aiFacts(scope,id){
 if(scope==='demo')return demonstration().input;
 if(scope==='plan')return planAnalysisInput(state,id);
 const facts=[],add=(id,label,value,source)=>{if(value!==undefined&&value!==null&&String(value).trim())facts.push({id,label,value:String(value),source});};
 if(scope==='product'){
  const p=product(state,id);if(!p)return null;const edited=state.edits[id]?.confirmedAt,custom=!!state.customProducts?.[id];
  for(const [key,label] of [['name','商品'],['configuration','配置']])add(key,label,p[key],custom?'user_confirmed':'example');
  for(const [key,label] of [['purpose','当前困难与用途'],['existing','现有物品'],['budget','本次计划金额 HK$'],['emotion','体验期待'],['social','他人的影响']])add(key,label,p[key],edited?'user_confirmed':'example');
  add('price','当前候选到手价 HK$（非实时行情）',priceFor(state,p),custom?'user_confirmed':'example');
  add('fit','代码计算的计划内差额（不代表银行余额）',JSON.stringify(budgetFit(p.budget,priceFor(state,p))),'calculated');
 }else{
  const x=state.experience,b=x.basis;
  if(x.basisConfirmed)for(const [key,label] of [['occupation','职业'],['interests','兴趣'],['tasks','任务与困难'],['equipment','现有设备'],['skills','已有技能'],['future','未来安排'],['time','可投入时间'],['budget','可投入金额范围'],['priority','本次最重要的取舍']])add(key,label,b[key],'user_confirmed');
  add('emotion','体验期待',x.emotion,'user_confirmed');add('social','社会影响',x.social,'user_confirmed');
  if(x.readiness)add('readiness','用户记录的设备验证',x.readiness,'user_confirmed');add('limitation','实际限制',x.limitation,'user_confirmed');
  if(!facts.length)add('sample','演示情境，尚未确认属于用户','准备尝试本地 AI 创作；先检查现有设备能否完成实际任务，不假设必须购买显卡。','example');
 }
 return {scope,facts};
}
function aiSlot(scope,id){return scope+':'+(id||'');}
function aiPanel(scope='direction',id=''){
 const selectable=scope==='direction';if(selectable&&ui.analysisMode){if(ui.analysisMode==='demo')scope='demo';else if(ui.analysisMode.startsWith('plan:')&&planAnalysisInput(state,ui.analysisMode.slice(5))){scope='plan';id=ui.analysisMode.slice(5);}else ui.analysisMode='direction';}
 const slot=aiSlot(scope,id),entry=ai.results.get(slot),input=aiFacts(scope,id),stale=entry&&(entry.fingerprint!==JSON.stringify(input)||!entry.isDemo&&entry.language!==getLanguage()),busy=ai.pending?.slot===slot,error=ai.errors.get(slot);
 const roles={use:['正在使用的我','blue'],price:['精打细算的我','green'],emotion:['感受当下的我','amber'],social:['在意形象的我','purple']};
 return `<section class="ai-section section" aria-label="Poe 实时分析"><div class="ai-bar"><div><p class="eyebrow">DEEPSEEK / FOUR PERSPECTIVES</p><h2>让四个我，回应这次的真实问题</h2><p class="caption">主动生成 · 先确认资料 · 不自动改变需求顺序或资金</p></div><div class="row wrap">${btn('本次依据与想法',scope==='product'?'edit-product':scope==='plan'?'ai-plan-notes':scope==='demo'?'ai-demo-info':'v2-basis','sm',`data-id="${e(id)}"`)}${btn('连接设置','ai-connect','sm')}${busy?btn('取消生成','ai-cancel','sm'):`<button class="btn primary sm" data-action="ai-preview" data-scope="${scope}" data-id="${e(id)}">${entry?'用 Poe 重新分析':'用 Poe 分析'} ${icon('spark','sm')}</button>`}</div></div>${selectable?analysisChooser(scope,id):''}${scope==='plan'?`<p class="hint">正在重评：${e(savedAnalysisOptions(state).find(x=>x.id===id)?.title)}。仅分析所选记录与资金摘要；不自动修改原计划。初始示例仍标为示例。</p>`:scope==='demo'?'<p class="hint">独立演示 · 自动带入耳机案例并展示脚本结果；无需密钥，不修改你的资料和计划。可另行点击 Poe 进行真实分析。</p>':''}<div class="ai-basis-summary"><p class="caption">本次资料：${input.facts.filter(f=>f.source==='user_confirmed').length} 条用户确认 · ${input.facts.filter(f=>f.source==='example').length} 条示例。${scope==='demo'?'当前只演示示例，不会覆盖你的实际资料。':input.facts.some(f=>f.source==='user_confirmed')?'填写过的想法可以继续修改。':'建议先补充自己的实际情况，避免只分析示例。'}</p></div><p class="caption ai-state" role="status" aria-live="polite">${busy?'正在请求 Poe，请稍候…':error?uiEscape(error):stale?'资料已变化：下面保留的是上次分析，请重新生成。':entry?(entry.isDemo?'演示脚本 · 非实时 AI · ':'已生成 · ')+e(entry.model)+' · '+new Date(entry.generatedAt).toLocaleString('zh-CN'):(ai.key||ai.access)?'已填写连接资料，确认本次依据后开始。':'尚未连接 · 支持你的 Poe API Key'}</p>${entry?`<div class="ai-result ${stale?'ai-stale':''}"><p class="ai-summary">${e(entry.result.summary)}</p><p class="caption">${entry.isDemo?'以下为预设演示脚本，便于理解流程，不代表本次调用了 AI。':'AI 生成的建议，可能不准确。引用示例的部分仍为示例；不代表实时价格或个人事实。'}</p><div class="agent-grid">${entry.result.perspectives.map(v=>`<article class="agent-card ${roles[v.key][1]}"><div class="between"><h3>${roles[v.key][0]}</h3>${btn('ⓘ','v2-agent-help','text-btn',`data-key="${v.key}"`)}</div><p class="agent-quote">${e(v.quote)}</p><div class="agent-source"><p>依据：${v.evidenceIds.length?v.evidenceIds.map(key=>{const f=entry.input.facts.find(f=>f.id===key);return e(f.label)+'（'+e({example:'示例',calculated:'代码计算',user_confirmed:'用户确认'}[f.source])+'）：'+e(f.value);}).join('；'):e(evidenceMessage(v.key,entry.input.facts,v.evidenceIds))}</p><p>待确认：${e(v.unknown)}</p><p>下一步：${e(v.nextAction)}</p></div>${btn('查看／补充依据',scope==='product'?'edit-product':scope==='plan'?'ai-plan-notes':scope==='demo'?'ai-demo-info':'v2-basis','text-btn',`data-id="${e(id)}" data-key="${v.key}"`)}</article>`).join('')}</div>${entry.result.suggestions.map((s,i)=>`<article class="source-card"><h3>${e(s.title)}</h3><p>为什么与你有关：${e(s.reason)}</p><p>下一步：${e(s.nextAction)}</p><div class="row wrap">${!stale&&!entry.dismissed?.includes(i)?btn('加入需求前确认','ai-add','sm',`data-slot="${e(slot)}" data-index="${i}"`)+btn('暂不考虑','ai-dismiss','text-btn',`data-slot="${e(slot)}" data-index="${i}"`):'<span class="caption">'+(stale?'资料已变化，请重新生成后再处理。':'本次暂不考虑')+'</span>'}</div></article>`).join('')}</div>`:''}</section>`;
}
async function aiConnect(){
 openDrawer('连接 Poe',`<p class="body">使用你自己的 Poe API Key。密钥仅保存在当前标签页内存，刷新或退出后清除，不写入计划、导出文件或网页源码。</p><p class="caption">调用经过本项目的服务端转发至 Poe，费用由对应 API 账户承担。仅点击“确认并生成”时发送你预览过的资料。</p><form id="ai-connect-form">${field('apiKey','Poe API Key','','password','留空保留本标签页已填写的密钥。','autocomplete="off" maxlength="256"')}${ai.shared?field('accessCode','项目访问码（使用项目密钥时填写）','','password','与个人密钥二选一。','autocomplete="off"'):''}<p id="ai-connect-error" class="field-error" role="alert"></p><div class="drawer-actions"><button class="btn primary" type="submit">保存到当前标签页</button>${btn('清除连接','ai-disconnect','sm')}</div></form><div class="source-card"><h3>项目设计文件</h3><p>沿用现有 My Best Choice 设计，设计稿与网站可分别打开。</p><a href="https://www.figma.com/design/IaQeWlPQ22QgeOKLoQH3I5" target="_blank" rel="noopener noreferrer" class="text-btn">打开 Figma 设计 ↗</a></div>`);
 try{const response=await fetch('/api/ai/status',{cache:'no-store'});if(response.ok){const status=await response.json();if(ai.shared!==status.shared){ai.shared=status.shared;if($('#ai-connect-form'))aiConnect();}}}catch{/* connection form remains usable without discovery */}
}
function aiPreview(scope,id){
 const input=aiFacts(scope,id);if(!input)return;ai.preview={input,scope,id,user:currentUser,language:getLanguage(),fingerprint:JSON.stringify(input)};
 openDrawer('确认本次发送的资料',`<p class="body">这些资料将发送至 Poe 生成四个视角。不会发送浏览器历史、聊天记录或整份账户档案。</p>${input.facts.map(f=>`<div class="source-card"><div class="between"><h3>${e(f.label)}</h3>${badge({example:'示例资料',user_confirmed:'用户确认',calculated:'代码计算'}[f.source],'outline')}</div><p>${e(f.value)}</p></div>`).join('')}<div class="source-card"><h3>四个视角分别有什么依据</h3>${[['use','使用'],['price','金额与时间'],['emotion','体验期待'],['social','他人影响']].map(([key,label])=>`<p>${label}：${relatedEvidence(key,input.facts).filter(f=>f.source==='user_confirmed').length?'已填写相关陈述':e(evidenceMessage(key,input.facts))}</p>`).join('')}${btn('修改本次依据',scope==='product'?'edit-product':scope==='plan'?'ai-plan-notes':scope==='demo'?'ai-demo-info':'v2-basis','sm',`data-id="${e(id)}"`)}</div><p class="hint">AI 只给建议。不会自动建立需求、改顺序、动用预留或替你购买。</p>${!ai.key&&!ai.access?'<p class="body">请先连接你的 API Key，再重新打开本次分析。</p>'+btn('连接 Poe','ai-connect','primary'):btn('确认并生成','ai-generate','primary')}`);
}
async function aiGenerate(){
 const p=ai.preview;if(!p||p.user!==currentUser||p.language!==getLanguage()||p.fingerprint!==JSON.stringify(aiFacts(p.scope,p.id))){toast('资料已变化，请重新确认。');return;}
 ai.pending?.controller.abort();const slot=aiSlot(p.scope,p.id),controller=new AbortController(),job={slot,controller};ai.pending=job;ai.errors.delete(slot);closeDrawer();refresh();
 try{const response=await fetch('/api/ai/analyze',{method:'POST',headers:{'Content-Type':'application/json','X-MBC-Language':getLanguage(),...(ai.key?{'X-Poe-Key':ai.key}:{'X-MBC-Access-Code':ai.access})},body:JSON.stringify(p.input),signal:controller.signal});const body=await response.json();if(!response.ok)throw Error(body.error||'连接失败，请重试。');if(ai.pending!==job||p.user!==currentUser)return;ai.results.set(slot,{...body,input:p.input,language:p.language,fingerprint:p.fingerprint,dismissed:[]});}
 catch(error){if(ai.pending===job&&error.name!=='AbortError')ai.errors.set(slot,error.message==='Failed to fetch'?'网络连接失败，请稍后重试。':error.message);}
 finally{if(ai.pending===job){ai.pending=null;refresh();}}
}
function aiClear(){ai.pending?.controller.abort();ai.pending=null;ai.key='';ai.access='';ai.preview=null;ai.results.clear();ai.errors.clear();ui.analysisMode='direction';}
document.addEventListener('click',ev=>{
 const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='logout'||a==='reset-confirm'){aiClear();return;}if(!a.startsWith('ai-'))return;ev.preventDefault();
 if(a==='ai-demo')aiRunDemo();else if(a==='ai-demo-info')aiDemoInfo();else if(a==='ai-plan-select')aiSelectPlan(el.dataset.plan);else if(a==='ai-plan-notes')aiPlanNotes(el.dataset.id);else if(a==='ai-connect')aiConnect();else if(a==='ai-preview')aiPreview(el.dataset.scope,el.dataset.id);else if(a==='ai-generate')aiGenerate();else if(a==='ai-cancel'){ai.pending?.controller.abort();ai.pending=null;refresh();}else if(a==='ai-disconnect'){aiClear();closeDrawer();refresh();toast('已清除本标签页的连接和分析。');}
 else if(a==='ai-dismiss'){const entry=ai.results.get(el.dataset.slot);if(entry){entry.dismissed.push(Number(el.dataset.index));refresh();}}
 else if(a==='ai-add'){const entry=ai.results.get(el.dataset.slot),s=entry?.result.suggestions[Number(el.dataset.index)];if(!s)return;const [scope,...rest]=el.dataset.slot.split(':');if(entry.fingerprint!==JSON.stringify(aiFacts(scope,rest.join(':')))){toast('资料已变化，请重新生成。');return;}needForm();$('#v2-need-form [name="title"]').value=s.title;$('#v2-need-form [name="problem"]').value=s.reason+'；下一步：'+s.nextAction;}
});
document.addEventListener('submit',ev=>{if(ev.target.id!=='ai-connect-form')return;ev.preventDefault();const f=new FormData(ev.target),key=String(f.get('apiKey')||'').trim(),access=String(f.get('accessCode')||'').trim();if(key&&(key.length<8||key.length>256)){const n=$('#ai-connect-error');n.textContent=translateText('请填写完整的 Poe API Key。');return;}if(key){ai.key=key;ai.access='';}else if(access){ai.access=access;ai.key='';}if(!ai.key&&!ai.access){$('#ai-connect-error').textContent=translateText('请填写 API Key。');return;}ev.target.reset();closeDrawer();refresh();toast('已暂存连接；首次生成时验证密钥。');});

function analysisChooser(scope,id){const options=savedAnalysisOptions(state),value=scope==='plan'?'plan:'+id:scope;return `<div class="analysis-chooser"><div class="field"><label for="ai-context">本次分析内容</label><select id="ai-context"><option value="direction" ${value==='direction'?'selected':''}>我的新方向与想法</option><option value="demo" ${value==='demo'?'selected':''}>耳机购买 · 独立演示案例</option>${options.length?`<optgroup label="之前保存的计划与需求">${options.map(x=>`<option value="plan:${e(x.id)}" ${value==='plan:'+x.id?'selected':''}>${e(x.kind)} · ${e(x.title)}</option>`).join('')}</optgroup>`:''}</select></div>${btn('一键看耳机演示','ai-demo','sm')}<p class="caption">演示自动展示完整案例；选择已有记录后，确认资料再交给 Poe 分析。</p></div>`;}
function aiRunDemo(){ai.pending?.controller.abort();ai.pending=null;ai.preview=null;const d=demonstration();ui.analysisMode='demo';ai.errors.delete('demo:');ai.results.set('demo:',{input:d.input,result:d.result,model:'耳机购买案例',generatedAt:new Date().toISOString(),fingerprint:JSON.stringify(d.input),isDemo:true,dismissed:[]});closeDrawer();refresh();}
function aiDemoInfo(){const d=demonstration();openDrawer('耳机演示案例的依据',`<p class="body">以下内容全部是独立示例，没有复制到你的个人资料。点击一键演示可重放；选择原计划即可回到真实记录。</p>${d.input.facts.map(f=>`<div class="source-card"><h3>${e(f.label)} · 示例</h3><p>${e(f.value)}</p></div>`).join('')}${btn('重新演示','ai-demo','primary sm')}`);}
function aiSelectPlan(id){const options=savedAnalysisOptions(state),selected=options.find(x=>x.id===id)||options[0];ui.analysisMode=selected?'plan:'+selected.id:'direction';goto('/proposals');if(!selected)toast('还没有保存的计划，可以先体验演示，或前往我的需求建立。');}
function aiPlanNotes(id){if(!planAnalysisInput(state,id))return;const notes=state.experience.analysisNotes?.[id]||{};openDrawer('补充这项计划的想法',`<p class="body">只用于当前选中的计划，不套用其他商品的体验或他人影响，也不修改原目标金额。</p><form id="ai-plan-notes-form" data-id="${e(id)}">${textarea('existing','现有办法与替代方案',notes.existing||'')}${textarea('priority','这次重评最重要的取舍',notes.priority||'')}${textarea('emotion','这项计划的体验期待',notes.emotion||'')}${textarea('social','这项计划的他人影响',notes.social||'')}<p class="hint">留空表示未知；保存不会自动调用 AI。</p><button class="btn primary" type="submit">保存本次补充</button></form>`);}
document.addEventListener('change',ev=>{if(ev.target.id!=='ai-context')return;const value=ev.target.value;if(value==='demo'){aiRunDemo();return;}if(value==='direction'||value.startsWith('plan:')&&planAnalysisInput(state,value.slice(5))){ui.analysisMode=value;closeDrawer();refresh();}});
document.addEventListener('submit',ev=>{const form=ev.target;if(form.id!=='ai-plan-notes-form')return;ev.preventDefault();const id=form.dataset.id;if(!planAnalysisInput(state,id)){toast('原计划已不存在，请重新选择。');return;}const f=new FormData(form);state.experience.analysisNotes||={};state.experience.analysisNotes[id]=Object.fromEntries(['existing','priority','emotion','social'].map(k=>[k,String(f.get(k)||'').trim()]));persist();closeDrawer();refresh();toast('已保存这项计划的补充，原计划金额未改变。');});
function commerceAuthHeaders(){return {'Content-Type':'application/json','X-MBC-Language':getLanguage(),...(ai.key?{'X-Poe-Key':ai.key}:{'X-MBC-Access-Code':ai.access})};}
async function commerceIdentify(form){
 const f=new FormData(form),url=String(f.get('url')||'').trim(),text=String(f.get('description')||'').trim();ui.importDraft={url,text};
 if(!url&&!text){manualProduct(String(f.get('productName')||''));return;}
 if(!url){manualProduct(String(f.get('productName')||text));return;}
 let link;try{link=marketplaceLink(url);}catch(error){$('#add-error').textContent=translateText(error.message);return;}
 if(!ai.key&&!ai.access){$('#add-error').textContent=translateText('先点击“连接 AI”，填写项目访问码或你的 API Key；输入的链接与描述已暂存。');return;}
 const job={controller:new AbortController(),user:currentUser};commerce.active?.controller.abort();commerce.active=job;commerce.result=null;commerce.error='';render(false);
 try{const r=await fetch('/api/products/identify',{method:'POST',headers:commerceAuthHeaders(),body:JSON.stringify({url:link.url,text}),signal:job.controller.signal});const data=await r.json();if(!r.ok)throw Error(data.error||'商品识别失败。');if(commerce.active!==job||currentUser!==job.user)return;commerce.result=data;commerce.user=currentUser;render(false);commercePreview();}
 catch(error){if(commerce.active===job&&error.name!=='AbortError'){commerce.error=error.message==='Failed to fetch'?'网络连接失败，请稍后重试。':error.message;render(false);}}
 finally{if(commerce.active===job){commerce.active=null;render(false);}}
}
function commercePreview(){const r=commerce.result;if(!r||commerce.user!==currentUser)return;const value=k=>r.fields[k]?.value||'';const original=[value('currency'),value('price')].filter(Boolean).join(' ');
 openDrawer('核对 AI 识别的商品',`<div class="row wrap">${badge(marketplaceNames[r.link.platform],'green')}${badge(r.aiUsed?'Poe 已提取 · 未由平台核实':'只识别到平台与编号','amber')}</div><p class="body">${e(r.notice)}</p><p class="caption">商品编号：${e(r.link.id)} · <a href="${e(r.link.url)}" target="_blank" rel="noopener noreferrer">查看商品原页 ↗</a></p><form id="commerce-confirm-form">${field('name','商品名称',value('name'),'text','','required maxlength="500"')}${field('model','型号／产品编号',value('model'),'text','商品编号不是制造商型号；无法确认可写“型号待核对”。','required maxlength="500"')}${field('configuration','所选版本／颜色／容量／保修',value('configuration'),'text','不要把未核实的保修当作已提供。','required maxlength="500"')}<div class="source-card"><h3>原币报价：${e(original||'尚未识别')}</h3><p class="caption">这是页面或你粘贴描述中的记录，不保证当前可成交。其他币种不会自动当作 HK$。</p></div>${field('priceHKD','本次记录的 HK$ 完整到手价（可留空）',value('currency')==='HKD'?value('price'):'','number','仅填写你核对后的港币金额；没有确认时不进行财务适配计算。','min="0" step="0.01"')}<label class="check-row"><input name="confirmed" type="checkbox" required>我已核对以上商品信息，了解它不是平台官方实时认证结果。</label><div class="drawer-actions"><button class="btn primary" type="submit">确认后加入商品</button>${btn('取消，不保存','close-drawer','sm')}</div></form><details class="source-card"><summary>查看识别来源与原文</summary>${Object.entries(r.fields).filter(([k,v])=>v.value!=null).map(([k,v])=>`<p><strong>${e(({name:'名称',brand:'品牌',model:'型号',configuration:'配置',price:'价格',currency:'币种',seller:'卖家'})[k])}</strong>：${e(v.value)}<br><span class="caption">${v.evidenceIds.map(id=>{const f=r.facts.find(f=>f.id===id);return e(f?.label||'来源待核对');}).join('；')}</span></p>`).join('')}${r.facts.map(f=>`<p class="caption">${e(f.label)}：${e(f.value)}</p>`).join('')}</details>`);
}
function commerceConnections(){openDrawer('商品识别与平台数据连接',`<p class="body">Poe 负责从资料中提取字段，不会替代平台授权。当前可识别完整链接、尝试读取公开页面，并整理你主动粘贴的描述。</p>${[['淘宝／天猫','淘宝开放平台 AppKey、AppSecret 及对应商品接口权限','https://developer.alibaba.com/docs/api.htm?apiId=28383'],['京东','通过审核的京东开放平台应用及适用接口凭证','https://jos.jd.com/commondoc?listId=306'],['亚马逊','Amazon Associates／Creators API 资格与凭证','https://affiliate-program.amazon.com/creatorsapi/docs/en-us/onboarding']].map(([name,need,url])=>`<div class="source-card"><div class="between"><h3>${name}</h3>${badge('官方数据未接入','amber')}</div><p>需要：${need}。</p><a class="text-btn" href="${url}" target="_blank" rel="noopener noreferrer">查看官方接入说明 ↗</a></div>`).join('')}<p class="hint">当前不自动抓取账号、订单、库存或评价，也不绕过登录与验证。价格历史与评价只有取得实际数据来源后才能显示为真实资料。</p>${btn('设置 Poe 连接','ai-connect','primary sm')}`);}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a==='logout'||a==='reset-confirm'){commerce.active?.controller.abort();commerce.active=null;commerce.result=null;commerce.error='';ui.importDraft=null;return;}if(a==='commerce-connections')commerceConnections();else if(a==='commerce-preview')commercePreview();else if(a==='commerce-cancel'){commerce.active?.controller.abort();commerce.active=null;commerce.error='已取消本次识别。';render(false);}else if(a==='commerce-manual')manualProduct(ui.importDraft?.text||'',ui.importDraft?.url||'');});
document.addEventListener('submit',ev=>{const form=ev.target;if(form.id!=='commerce-confirm-form')return;ev.preventDefault();const r=commerce.result;if(!r||commerce.user!==currentUser){toast('识别结果已失效，请重新识别。');return;}const f=new FormData(form),v=k=>String(f.get(k)||'').trim();if(!f.has('confirmed')||!v('name')||!v('model')||!v('configuration'))return;const price=v('priceHKD')===''?null:Number(v('priceHKD'));if(price!=null&&(!Number.isFinite(price)||price<0)){toast('请填写有效的港币金额，或留空。');return;}const id='custom-'+Date.now().toString(36);state.customProducts||={};state.customProducts[id]={id,name:v('name'),model:v('model'),configuration:v('configuration'),price,sourceUrl:r.link.url,category:marketplaceNames[r.link.platform],art:/耳机|headphone|earbud/i.test(v('name'))?'earbuds':'stand',budget:null,purpose:'尚未确认本次用途',existing:'现有替代办法待填写',emotion:'',social:'',tag:'AI 辅助导入 · 用户确认记录',importRecord:{platform:r.link.platform,productId:r.link.id,originalPrice:r.fields.price.value,currency:r.fields.currency.value,fields:r.fields,identifiedAt:r.generatedAt,pageStatus:r.pageStatus,officialVerified:false},confirmedAt:new Date().toISOString()};persist();commerce.result=null;ui.importDraft=null;closeDrawer();goto('/products/'+id);toast('商品资料已保存；用途、预算及真实市场证据仍可继续补充。');});

function languageButton(){return `<button class="btn sm lang-toggle" data-action="language-toggle" aria-label="${getLanguage()==='en'?'Switch to Chinese':'切换到英文'}" title="${getLanguage()==='en'?'Switch to Chinese':'切换到英文'}">${getLanguage()==='en'?'中文':'English'}</button>`;}
function syncLanguageShell(){document.documentElement?.setAttribute('lang',getLanguage());const skip=document.querySelector('.skip-link');if(skip)skip.textContent=getLanguage()==='en'?'Skip to content':'跳至主要内容';const meta=document.querySelector('meta[name="description"]');meta?.setAttribute?.('content',getLanguage()==='en'?'Compare price and quality, plan purchases, and keep the reasons behind your decisions.':'比较价格与质量，提前安排想买的东西，留下每次决定的理由。');}
function captureLanguageDrafts(){if(!document.querySelectorAll)return [];return [...document.querySelectorAll('form')].map(form=>({id:form.id,controls:[...form.elements].map(el=>({value:el.value,checked:el.checked,selected:el.tagName==='SELECT'?[...el.options].map(o=>o.selected):null}))}));}
function restoreLanguageDrafts(drafts){for(const draft of drafts){const form=document.getElementById(draft.id);if(!form?.elements)continue;[...form.elements].forEach((el,i)=>{const value=draft.controls[i];if(!value)return;if(el.type!=='file')el.value=value.value;if(typeof value.checked==='boolean')el.checked=value.checked;if(value.selected&&el.options)[...el.options].forEach((o,j)=>o.selected=value.selected[j]||false);});}}
document.addEventListener('click',ev=>{if(!ev.target.closest('[data-action="language-toggle"]'))return;ev.preventDefault();const drafts=captureLanguageDrafts(),drawer=drawerSource,scroll=window.scrollY;setLanguage(getLanguage()==='en'?'zh-CN':'en');render(false);if(drawer)openDrawer(drawer.title,drawer.content,{wide:drawer.wide,eyebrow:drawer.eyebrow});restoreLanguageDrafts(drafts);window.scrollTo(0,scroll);});
